window.CARDS_L={"Rigveda 3.62.10": ["ரிக் வேதம் 3.62.10", "காயத்ரி மந்திரம்", "அந்த சவிதா தேவனின் மேலான, புனிதமான ஒளியை நாங்கள் தியானிக்கிறோம். அது எங்கள் அறிவை நல்வழியில் தூண்டட்டும்.", "இது செல்வத்திற்கோ பொருட்களுக்கோ அல்ல, தூய்மையான நல்ல அறிவுக்கான பிரார்த்தனை. சூரியன் உலகிற்கு ஒளி தருவது போல, சரியான முடிவுகள் எடுக்க எங்கள் சிந்தனைக்கு ஒளி தா என்று இறைவனிடம் வேண்டுகிறோம். தொடக்கத்தில் உள்ள \"ஓம் பூர்புவஃ ஸ்வஃ\" சொற்கள் மரபில் பின்னர் சேர்க்கப்பட்டவை; அவை ரிக் வேதத்தின் மூல மந்திரத்தின் பகுதி அல்ல."], "Rigveda 1.1.1": ["ரிக் வேதம் 1.1.1", "ரிக் வேதத்தின் முதல் மந்திரம்", "முன்னோடியும், யாகத்தின் தேவனும், ருத்விக்கும், தேவர்களை அழைப்பவனும், அனைத்திலும் மேலாக ரத்தினங்களை அளிப்பவனுமான அக்னியை நான் துதிக்கிறேன்.", "மிகப் பழமையான வேதம் அக்னியுடன் தொடங்குகிறது. அக்னி மனிதனுக்கும் இறைவனுக்கும் இடையிலான பாலம்: அதில் அர்ப்பணிக்கப்படுவது மேலே சென்றடைகிறது. அக்னி ஆற்றல், உழைப்பு, ஞான ஒளியின் சின்னமும் கூட; ஆகவேதான் இன்றும் ஒவ்வொரு சுபநிகழ்விலும் விளக்கேற்றப்படுகிறது அல்லது ஹோமம் செய்யப்படுகிறது."], "Rigveda 1.164.46": ["ரிக் வேதம் 1.164.46", "உண்மை ஒன்றே, ஞானிகள் அதைப் பல பெயர்களில் அழைக்கின்றனர்", "அதை இந்திரன், மித்ரன், வருணன், அக்னி என்கின்றனர்; அதுவே தெய்வீக சுபர்ண கருத்மான். உண்மை ஒன்றே, அறிஞர்கள் அதைப் பல பெயர்களில் சொல்கின்றனர்: அக்னி, யமன், மாதரிஸ்வா.", "பல தெய்வங்கள் ஒரே பரம உண்மையின் பல வடிவங்கள்; ஒரே மனிதரை ஒருவர் \"அப்பா\" என்றும், ஒருவர் \"மகன்\" என்றும், ஒருவர் \"ஆசிரியர்\" என்றும் அழைப்பது போல. இந்த வரியே இந்து சகிப்புத்தன்மையின் வேர்: உண்மை ஒன்று, பெயர்கள் பல என்னும்போது பெயர்களுக்காகச் சண்டையிடுவதில் பொருள் இல்லை."], "Rigveda 10.90.1": ["ரிக் வேதம் 10.90.1", "புருஷ சூக்தம்: விராட் புருஷன்", "விராட் புருஷனுக்கு ஆயிரம் தலைகள், ஆயிரம் கண்கள், ஆயிரம் கால்கள். அவன் பூமியை எல்லாப் புறமும் வியாபித்து அதற்கும் பத்து விரல் அளவு அப்பால் நிற்கிறான்.", "\"சஹஸ்ரம்\" என்றால் \"எண்ணற்ற.\" எல்லா உயிர்களின் தலைகளும் கண்களும் கால்களும் அந்த ஒரே பரமாத்மாவின் அங்கங்கள். இறைவன் உலகிற்குள்ளும் இருக்கிறான், அதைவிடப் பெரியவனாகவும் இருக்கிறான். இந்த சூக்தம் ஏறக்குறைய ஒவ்வொரு பூஜையிலும் ஹோமத்திலும் ஓதப்படுகிறது."], "Rigveda 7.59.12": ["ரிக் வேதம் 7.59.12", "மகா ம்ருத்யுஞ்ஜய மந்திரம்", "மூன்று கண்களை உடைய, நறுமணமுள்ள, அனைவரையும் போஷிக்கும் சிவனை நாங்கள் வழிபடுகிறோம். பழுத்த வெள்ளரிக்காய் தானாகக் கொடியிலிருந்து விடுபடுவது போல, அவர் எங்களை மரணத்தின் பந்தத்திலிருந்து விடுவிக்கட்டும், அமிர்தத்திலிருந்து அல்ல.", "பழுத்த வெள்ளரிக்காய் சிரமமின்றிக் கொடியிலிருந்து பிரிகிறது. இந்த மந்திரம் வாழ்வில் அதே முதிர்ச்சியை வேண்டுகிறது: முழுமையாக வளர்வது, பயத்தை விடுவது, நேரம் வரும்போது அமைதியாக விடைபெறுவது. மக்கள் இதை ஆரோக்கியத்திற்கும் தைரியத்திற்கும் ஜபிக்கின்றனர்."], "Rigveda 10.191.2": ["ரிக் வேதம் 10.191.2", "சங்கதன சூக்தம்: சேர்ந்து நடங்கள், சேர்ந்து பேசுங்கள்", "சேர்ந்து நடங்கள், சேர்ந்து பேசுங்கள், உங்கள் மனங்கள் ஒன்றையொன்று புரிந்துகொள்ளட்டும்; பண்டைய தேவர்கள் ஒருமனதாகத் தங்கள் பங்கை ஏற்றது போல.", "இது முழு ரிக் வேதத்தின் கடைசி சூக்தம், இதன் பொருள் ஒற்றுமை. குடும்பங்கள், கிராமங்கள், நாடுகள் மக்கள் ஒரே திசையில் நடந்து, ஒருவருக்கொருவர் பேசி, புரிந்துகொள்ளும்போதுதான் முன்னேறுகின்றன."], "Samaveda 1 (also Rigveda 6.16.10)": ["சாம வேதம் 1 (ரிக் வேதம் 6.16.10-இலும்)", "சாம வேதத்தின் முதல் மந்திரம்", "ஓ அக்னியே! துதியைக் கேட்டு எங்கள் ஆஹுதிகளை ஏற்க வருக, ஹோதாவாகப் புனிதமான தர்ப்பை ஆசனத்தில் அமர்வாயாக.", "சாம வேதம் எப்படி உருவானது என்பது இதிலிருந்து புரிகிறது: ரிக் வேத மந்திரம் எடுக்கப்பட்டு இசையாக்கப்பட்டது. அதே சொற்கள் ஸ்வரத்துடன் பாடப்படும்போது, பிரார்த்தனை புரிந்துகொள்ளப்படுவதோடு உணரவும் படுகிறது."], "Atharvaveda 12.1.12 (part)": ["அதர்வ வேதம் 12.1.12 (பகுதி)", "பூமி சூக்தம்: பூமி என் தாய்", "பூமி என் தாய், நான் பூமியின் மகன்.", "பூமி சூக்தத்தின் 63 மந்திரங்களில் பூமி, அதன் நதிகள், மலைகள், தாவரங்கள், எல்லா மக்கள் மீதும் அன்பு உள்ளது. பூமி தாய் என்றால், அதற்குத் தீங்கு செய்வது பாவம். இது உலகின் மிகப் பழமையான சுற்றுச்சூழல் பிரார்த்தனைகளில் ஒன்று. ஆகவேதான் பலர் காலையில் படுக்கையிலிருந்து இறங்கும் முன் பூமியை வணங்குகின்றனர்."], "Rigveda 1.89.1 (first line)": ["ரிக் வேதம் 1.89.1 (முதல் வரி)", "எல்லாப் புறமிருந்தும் நல்ல எண்ணங்கள் வரட்டும்", "எல்லாப் புறமிருந்தும் எங்களிடம் மங்களமான எண்ணங்கள் வரட்டும்.", "மனதைத் திறந்து வையுங்கள். நல்ல எண்ணங்கள் எங்கிருந்தும் யாரிடமிருந்தும் வரலாம், ஆகவே அனைவரிடமிருந்தும் கற்கத் தயாராக இருங்கள்."], "Isha Upanishad 1 (Yajurveda 40.1)": ["ஈசாவாஸ்ய உபநிடதம் 1 (யஜுர் வேதம் 40.1)", "ஈசாவாஸ்யம்: எல்லாவற்றிலும் இறைவன்", "இந்த உலகில் உள்ள அனைத்தும் இறைவனால் நிறைக்கப்பட்டுள்ளன. தியாக மனப்பான்மையுடன் அதை அனுபவியுங்கள். யாருடைய செல்வத்தின் மீதும் பேராசை கொள்ளாதீர்கள்; உண்மையில் செல்வம் யாருடையது?", "தேவைக்கு ஏற்பப் பயன்படுத்தி வாழ்க்கையை அனுபவியுங்கள், ஆனால் ஒட்டிக்கொள்ளாதீர்கள், பறிக்காதீர்கள். அனைத்தும் இறைவனுடையது; நாம் சிறிது காலத்திற்குக் காவலர்கள் மட்டுமே. எல்லா உபநிடதங்களும் அழிந்து இந்த ஒரு மந்திரம் மட்டும் மிஞ்சினாலும் இந்து மதம் வாழும் என்று மகாத்மா காந்தி சொன்னார்."], "Brihadaranyaka Upanishad 1.3.28": ["பிருஹதாரண்யக உபநிடதம் 1.3.28", "அஸதோ மா ஸத்கமய", "என்னைப் பொய்மையிலிருந்து உண்மைக்கு அழைத்துச் செல். இருளிலிருந்து ஒளிக்கு அழைத்துச் செல். மரணத்திலிருந்து அமரத்துவத்திற்கு அழைத்துச் செல்.", "வளர்ச்சியின் மூன்று படிகள்: தவறான எண்ணங்களிலிருந்து உண்மைக்கு, அறியாமையிலிருந்து ஞானத்திற்கு, மரண பயத்திலிருந்து அழியாத ஆத்மாவின் அறிவுக்கு. இது ஒவ்வொரு மாணவனின், ஒவ்வொரு மனிதனின் பிரார்த்தனை."], "Taittiriya and Katha Upanishads": ["தைத்திரீய மற்றும் கட உபநிடதங்கள்", "சாந்தி பாடம்: ஸஹ நாவவது", "இறைவன் நம் இருவரையும் (குருவும் சீடனும்) காக்கட்டும். நம் இருவரையும் போஷிக்கட்டும். சேர்ந்து முயற்சி செய்வோமாக. நாம் கற்றது ஒளிமிக்கதாக அமையட்டும். நாம் ஒருபோதும் ஒருவரையொருவர் வெறுக்காமல் இருப்போமாக. ஓம் சாந்தி, சாந்தி, சாந்தி.", "கல்விக்கு முன் குருவும் சீடனும் சமமாக ஒருவர் நலனுக்காக மற்றவர் பிரார்த்திக்கின்றனர். \"சாந்தி\" மூன்று முறை சொல்லப்படுகிறது: ஆத்யாத்மிக (தன் உடல்-மனத்திலிருந்து), ஆதிபௌதிக (சுற்றியுள்ள உலகிலிருந்து), ஆதிதைவிக (இயற்கைச் சக்திகளிலிருந்து) அமைதிக்காக."], "Katha Upanishad 1.3.14 (first line)": ["கட உபநிடதம் 1.3.14 (முதல் வரி)", "உத்திஷ்டத ஜாக்ரத", "எழுந்திருங்கள்! விழித்திருங்கள்! சிறந்த குருக்களிடம் சென்று ஞானம் பெறுங்கள்.", "சுவாமி விவேகானந்தர் இதைப் பிரபலமாக்கினார்: \"எழுமின், விழிமின், குறிக்கோளை அடையும் வரை நில்லாது செல்மின்.\" வாழ்க்கையைத் தூங்கிக் கழிக்காதீர்கள். விழித்தெழுங்கள், நல்ல குருக்களைத் தேடுங்கள், கற்றுக்கொண்டே இருங்கள்."], "Gita 2.47": ["கீதை 2.47", "கர்மண்யேவாதிகாரஸ்தே", "உனக்குச் செயல் செய்வதில் மட்டுமே உரிமை உண்டு, அதன் பலன்களில் ஒருபோதும் இல்லை. பலனின் ஆசையைச் செயலுக்குக் காரணமாக்காதே, செயலைக் கைவிடுவதிலும் மனதைச் செலுத்தாதே.", "மாணவன் மதிப்பெண் கவலையில் சிக்காமல் முழு மனதுடன் படிக்க வேண்டும். உன் கையில் உள்ள உழைப்பில் முழு மனதையும் செலுத்து. முடிவு பல விஷயங்களைப் பொறுத்தது, ஆகவே அதன் பயம் உன்னைத் தடுக்கக்கூடாது. இதைச் சோம்பலுக்குச் சாக்காகவும் ஆக்காதே."], "Gita 2.22": ["கீதை 2.22", "வாஸாம்ஸி ஜீர்ணானி", "மனிதன் பழைய ஆடைகளைக் களைந்து புதிய ஆடைகளை அணிவது போல, ஆத்மா பழைய உடலை விட்டுப் புதிய உடலை ஏற்கிறது.", "மரணம் உங்கள் முடிவு அல்ல. இந்த ஸ்லோகம் அன்புக்குரியவரை இழந்தவர்களுக்கு ஆறுதல் தருகிறது: நீங்கள் நேசித்த அந்த ஆத்மா அழிவதில்லை."], "Gita 4.7–4.8": ["கீதை 4.7–4.8", "யதா யதா ஹி தர்மஸ்ய", "ஓ பாரதா (அர்ஜுனா)! எப்போதெல்லாம் தர்மம் குன்றி அதர்மம் ஓங்குகிறதோ, அப்போதெல்லாம் நான் என்னை வெளிப்படுத்துகிறேன். நல்லோரைக் காக்கவும், தீயோரை அழிக்கவும், தர்மத்தை நிலைநாட்டவும் நான் யுகந்தோறும் அவதரிக்கிறேன்.", "இதுவே அவதாரக் கொள்கை: இறைவன் உலகைக் கைவிடுவதில்லை. அநீதி மிகும்போது அவர் ராமனாக, கிருஷ்ணனாக, பல வடிவங்களில் வருகிறார். இது நம்பிக்கையின் வாக்குறுதி."], "Gita 6.5": ["கீதை 6.5", "உத்தரேதாத்மனாத்மானம்", "உன்னால் உன்னையே உயர்த்திக்கொள், உன்னைத் தாழ்த்திக்கொள்ளாதே. மனிதன் தானே தனக்கு நண்பன், தானே தனக்குப் பகைவன்.", "உங்கள் வளர்ச்சியை வேறு யாரும் செய்ய முடியாது. கட்டுப்பட்ட மனம் சிறந்த நண்பன்; கட்டுப்படாத மனம் மிகப் பெரிய பகைவன். உங்கள் கடிவாளத்தை நீங்களே பிடியுங்கள்."], "Traditional prayer (Shubham Karoti)": ["பாரம்பரியப் பிரார்த்தனை (சுபம் கரோதி)", "தீப பிரார்த்தனை", "சுபம், நலம், ஆரோக்கியம், செல்வ வளம் தந்து பகை உணர்வை அழிக்கும் அந்த தீப ஜோதிக்கு வணக்கம். தீப ஜோதி பரப்பிரம்மம், தீப ஜோதி ஜனார்த்தனன். தீபம் என் பாவங்களைப் போக்கட்டும்; தீப ஜோதிக்கு வணக்கம்.", "பல இல்லங்களில் குழந்தைகள் ஒவ்வொரு மாலையும் விளக்கேற்றும்போது இதைச் சொல்கின்றனர். தீபாவளியின் முதல் பிரார்த்தனைக்கு இதுவே மிகப் பொருத்தமானது."], "Traditional mantra": ["பாரம்பரிய மந்திரம்", "லட்சுமி மந்திரம்", "ஓம், ஸ்ரீம், மகாலட்சுமிக்கு வணக்கம்.", "பூஜையில் இதை 11 அல்லது 108 முறை ஜபியுங்கள். லட்சுமி எல்லா வகையான வளத்தின் சின்னம்: ஆரோக்கியம், அறிவு, கருணை, பகிர்ந்துகொள்ளும் அளவு நிறைவு, வெறும் பணம் மட்டுமல்ல."], "Gita 1.1": ["கீதை 1.1", "முதல் கேள்வி", "திருதராஷ்டிரன் சொன்னான்: ஓ சஞ்சயா! தர்ம பூமியான குருக்ஷேத்திரத்தில் போரிடும் விருப்பத்துடன் கூடியிருக்கும் என் மகன்களும் பாண்டுவின் மகன்களும் என்ன செய்தனர்?", null], "Gita 2.20": ["கீதை 2.20", "ஆத்மா பிறப்பதுமில்லை, இறப்பதுமில்லை", "இந்த ஆத்மா ஒருபோதும் பிறப்பதுமில்லை, இறப்பதுமில்லை. இது தோன்றி மீண்டும் இல்லாமல் போவதுமில்லை. இது பிறப்பற்றது, நித்தியமானது, சாசுவதமானது, புராதனமானது. உடல் கொல்லப்பட்டாலும் இது இறப்பதில்லை.", "உடல் குழந்தைப் பருவத்திலிருந்து இளமைக்கும் முதுமைக்கும் மாறிக்கொண்டே இருக்கிறது, ஆனால் \"நீங்கள்\" அப்படியே இருக்கிறீர்கள். மாறாத அந்த \"நீங்கள்\" தான் ஆத்மா. இதை அறிவது மிக ஆழமான பயமான மரண பயத்தைப் போக்குகிறது."], "Gita 2.48": ["கீதை 2.48", "சமத்வம் யோக உச்யதே", "ஓ தனஞ்சயா! பற்றை விட்டு, யோகத்தில் நிலைத்துச் செயல்களைச் செய். வெற்றியிலும் தோல்வியிலும் சமமாக இரு. இந்தச் சமநிலையே யோகம் எனப்படுகிறது.", "யோகம் வெறும் ஆசனங்கள் அல்ல. யோகம் என்பது சமநிலையான மனம்: வெற்றியில் துள்ளாமல், தோல்வியில் உடையாமல் இருப்பது. அமைதியான மனம் வேலையையும் சிறப்பாகச் செய்கிறது."], "Gita 3.21": ["கீதை 3.21", "சிறந்தவர்களின் நடத்தை", "சிறந்த மனிதன் எப்படி நடக்கிறானோ, மற்றவர்களும் அப்படியே நடக்கின்றனர். அவன் நிறுவும் தரத்தையே உலகம் பின்பற்றுகிறது.", "குழந்தைகள் பெற்றோரைப் பின்பற்றுகின்றனர், அணி தன் தலைவரைப் பின்பற்றுகிறது. நீங்கள் பெற்றோரோ ஆசிரியரோ அதிகாரியோ என்றால், உங்கள் சொற்களை விட உங்கள் நடத்தையே அதிகம் கற்பிக்கிறது."], "Gita 3.35": ["கீதை 3.35", "ஸ்வதர்மமே சிறந்தது", "தன் தர்மம் குணமற்றதாக இருந்தாலும், நன்றாகக் கடைப்பிடிக்கப்பட்ட பிறர் தர்மத்தை விடச் சிறந்தது. தன் தர்மத்தில் இறப்பதும் நன்மையே; பிறர் தர்மம் பயம் தருவது.", "பிறரைப் பின்பற்றிக் கடன் வாங்கிய வாழ்க்கை வாழாதே. உன் இயல்புக்கும் பொறுப்புக்கும் ஏற்ப உண்மையில் உன் கடமை எதுவோ அதைச் செய், அதில் நீ முழுமையாக இல்லாவிட்டாலும்."], "Gita 4.38": ["கீதை 4.38", "ஞானத்தைப் போலத் தூய்மையானது எதுவுமில்லை", "இந்த உலகில் ஞானத்திற்கு இணையான தூய்மைப்படுத்தும் பொருள் எதுவுமில்லை. யோகத்தில் சித்தி பெற்றவன் காலப்போக்கில் அதைத் தனக்குள்ளேயே அடைகிறான்.", "அறியாமையே உண்மையான அழுக்கு. உண்மையான புரிதல் பயத்தையும் குற்ற உணர்வையும் குழப்பத்தையும் கழுவிவிடுகிறது; அது தொடர்ந்த பயிற்சியால் காலப்போக்கில் வளர்கிறது."], "Gita 5.10": ["கீதை 5.10", "தாமரை இலை போல", "எல்லாச் செயல்களையும் இறைவனுக்கு அர்ப்பணித்துப் பற்றை விட்டுச் செய்பவனைப் பாவம் ஒட்டுவதில்லை, நீரில் இருந்தும் நனையாத தாமரை இலை போல.", "தாமரை சேற்றில் வளர்ந்தாலும் தூய்மையாக இருக்கிறது. நீங்கள் குடும்பம், வேலை, செல்வத்துடன் உலகில் முழுமையாக வாழலாம், பேராசையும் அகங்காரமும் உங்களிடம் ஒட்டாமல்."], "Gita 5.18": ["கீதை 5.18", "பண்டிதாஃ ஸமதர்சினஃ", "ஞானிகள் கல்வியும் பணிவும் நிறைந்த அந்தணரையும், பசுவையும், யானையையும், நாயையும், சண்டாளனையும் சம பார்வையுடன் காண்கின்றனர்.", "உண்மையான ஞானம் ஒவ்வொரு உயிரிலும், அதன் சாதி, அந்தஸ்து, பிறப்பு எதுவாக இருந்தாலும், ஒரே ஆத்மாவைக் காண்கிறது. யாரையும் தாழ்வாக நினைப்பது ஞானத்தின் அடையாளம் அல்ல, அறியாமையின் அடையாளம்."], "Gita 6.17": ["கீதை 6.17", "முறையான உணவும் ஓய்வும்", "யாருடைய உணவும் பொழுதுபோக்கும் முறையானவையோ, செயல்களில் முயற்சி சமநிலையானதோ, தூக்கமும் விழிப்பும் ஒழுங்கானவையோ, அவருக்கு யோகம் எல்லாத் துன்பங்களையும் அழிக்கிறது.", "அதிகமும் வேண்டாம், குறைவும் வேண்டாம். சமநிலையான உணவு, போதுமான தூக்கம், ஒழுங்கான வேலை, சிறிது பொழுதுபோக்கு, இவையே எந்த ஆன்மீக வாழ்க்கைக்கும் அடித்தளம். மிகையால் எதுவும் கிடைப்பதில்லை."], "Gita 6.35": ["கீதை 6.35", "பயிற்சியும் வைராக்கியமும்", "ஓ மகாபாஹு! சந்தேகமின்றி மனம் சஞ்சலமானது, அதைக் கட்டுப்படுத்துவது கடினம். ஆனால் ஓ கௌந்தேயா! பயிற்சியாலும் வைராக்கியத்தாலும் அது கட்டுப்படுகிறது.", "மனதைக் கட்டுப்படுத்துவது கடினம் என்று ஸ்ரீ கிருஷ்ணரே ஒப்புக்கொள்கிறார், ஆகவே மனம் அலைந்தால் மனம் தளராதீர்கள். அதைத் திரும்பத் திரும்பக் கொண்டுவாருங்கள் (பயிற்சி), அலைக்கழிப்பவற்றின் மீதான ஆர்வத்தை மெல்லக் குறையுங்கள் (வைராக்கியம்)."], "Gita 7.7": ["கீதை 7.7", "நூலில் கோத்த முத்துகள் போல", "ஓ தனஞ்சயா! என்னை விட மேலானது எதுவும் இல்லை. இந்த உலகம் முழுவதும் நூலில் மணிகள் கோக்கப்பட்டது போல என்னிடம் கோக்கப்பட்டுள்ளது.", "மாலையில் முத்துகள் தெரிகின்றன, நூல் தெரிவதில்லை, ஆனால் நூலே அனைத்தையும் இணைத்து வைக்கிறது. ஒவ்வொரு மனிதரையும் ஒவ்வொரு பொருளையும் இணைக்கும் அந்தக் கண்ணுக்குத் தெரியாத நூலே இறைவன்."], "Gita 7.16": ["கீதை 7.16", "நான்கு வகை பக்தர்கள்", "ஓ அர்ஜுனா! நான்கு வகையான புண்ணியவான்கள் என்னை வழிபடுகின்றனர்: துன்பப்படுபவன் (ஆர்த்தன்), ஞானத்தை நாடுபவன் (ஜிக்ஞாசு), செல்வத்தை நாடுபவன் (அர்த்தார்த்தி), ஞானி.", "ஒருவர் துன்பத்தில் பிரார்த்திக்கிறார், ஒருவர் ஆர்வத்தால், ஒருவர் வெற்றிக்காக. ஸ்ரீ கிருஷ்ணர் அனைவரையும் நல்லவர்கள் என்கிறார், ஏனெனில் எந்தக் காரணத்திற்காகவும் இறைவனை நோக்கித் திரும்புவது ஒரு தொடக்கம். இறைவனை இறைவனுக்காகவே நேசிக்கும் ஞானி அனைவரிலும் பிரியமானவன்."], "Gita 8.5": ["கீதை 8.5", "இறுதிக் காலத்தில் நினைவு", "இறுதி நேரத்தில் என்னையே நினைத்தபடி உடலை விட்டுச் செல்பவன் என் சொரூபத்தை அடைகிறான், இதில் சந்தேகமில்லை.", "அதனால்தான் குடும்பங்கள் இறுதி நேரத்தில் ஒருவர் அருகே இறைவனின் நாமத்தைச் சொல்கின்றன. ஆழமான பாடம்: வாழ்நாள் முழுவதும் நாம் எதை அதிகம் நினைக்கிறோமோ, அதுவே இறுதியில் நினைவுக்கு வருகிறது."], "Gita 8.7": ["கீதை 8.7", "நினைவுகூர்ந்து செயல்படு", "ஆகவே எல்லா நேரங்களிலும் என்னை நினை, போரும் செய். மனதையும் புத்தியையும் எனக்கு அர்ப்பணித்து நீ நிச்சயமாக என்னை அடைவாய்.", "ஆன்மீக வாழ்க்கையும் உலகக் கடமைகளும் தனித்தனி அல்ல. வேலை செய்யும்போதும், குடும்பத்தை நடத்தும்போதும், சவால்களை எதிர்கொள்ளும்போதும் இறைவனை மனதில் வையுங்கள்."], "Gita 9.22": ["கீதை 9.22", "யோகக்ஷேமம் வஹாம்யஹம்", "வேறு எண்ணமின்றி என்னைச் சிந்தித்து வழிபடும், எப்போதும் என்னுடன் இணைந்திருக்கும் பக்தர்களின் யோகக்ஷேமத்தை (இல்லாததைப் பெறுதல், இருப்பதைக் காத்தல்) நானே சுமக்கிறேன்.", null], "Gita 9.26": ["கீதை 9.26", "பத்ரம் புஷ்பம் பலம் தோயம்", "எனக்கு அன்புடன் இலை, பூ, பழம் அல்லது நீர் அர்ப்பணிக்கும் தூய மனம் கொண்ட பக்தனின் அன்புக் காணிக்கையை நான் ஏற்கிறேன்.", "இறைவனுக்கு விலையுயர்ந்த காணிக்கைகள் தேவையில்லை. அன்புடன் சமர்ப்பிக்கும் ஒரு துளசி இலை ஆடம்பரத் தங்கத்தை விட மதிப்புமிக்கது. உண்மையான காணிக்கை அன்பே."], "Gita 10.20": ["கீதை 10.20", "அனைவரின் இதயத்திலும் உள்ள ஆத்மா நானே", "ஓ குடாகேசா (உறக்கத்தை வென்ற அர்ஜுனா)! எல்லா உயிர்களின் இதயத்திலும் இருக்கும் ஆத்மா நானே. எல்லா உயிர்களின் ஆதியும் நடுவும் முடிவும் நானே.", "இறைவனைத் தேடத் தொலைவு செல்ல வேண்டியதில்லை. வெளி விபூதிகளை எண்ணுவதற்கு முன், முதலில் ஒவ்வொரு இதயத்திற்குள்ளும் பார் என்கிறார் ஸ்ரீ கிருஷ்ணர்."], "Gita 10.41": ["கீதை 10.41", "ஒவ்வொரு சிறப்பும் இறைவனின் அம்சம்", "விபூதியும் அழகும் வலிமையும் கொண்ட எந்தப் பொருளும் என் தேஜஸின் அம்சத்திலிருந்து தோன்றியது என்று அறிவாயாக.", "ஒரு சிறந்த இசைக்கலைஞரை, ஒரு சூரிய உதயத்தை, ஒரு கருணைச் செயலை அல்லது ஒரு அற்புதமான எண்ணத்தைக் காணும்போது, நீங்கள் இறைவனின் ஒரு சிறு காட்சியைக் காண்கிறீர்கள். இதனால் சாதாரணப் பாராட்டும் பக்தியாகிறது."], "Gita 11.12": ["கீதை 11.12", "ஆயிரம் சூரியன்களை விட மிகுந்த ஒளி", "வானில் ஒரே நேரத்தில் ஆயிரம் சூரியன்களின் ஒளி உதித்தால், அது ஒருவேளை அந்த மகாத்மாவின் (விஸ்வரூபத்தின்) தேஜஸுக்கு இணையாகலாம்.", "எல்லையற்றதன் முன் சொற்கள் சிறுத்துப் போகின்றன. 1945-இல் முதல் அணுகுண்டு சோதனையின்போது கீதையின் இதே அத்தியாயம் தனக்கு நினைவுக்கு வந்ததாக விஞ்ஞானி ஜே. ராபர்ட் ஓப்பன்ஹைமர் சொன்னார்."], "Gita 11.32": ["கீதை 11.32", "காலோஸ்மி", "நான் உலகங்களை அழிக்கும் வளர்ந்த காலம், இங்கே அனைவரையும் அழிப்பதில் ஈடுபட்டுள்ளேன். நீ இல்லாமலும், எதிர்ப் படைகளில் நிற்கும் இந்த வீரர்கள் யாரும் இருக்க மாட்டார்கள்.", "பிறந்தது இறப்பது உறுதி; காலம் அனைவரையும் கொண்டு செல்கிறது. அர்ஜுனன் உண்மையான செயலாளி அல்ல. பெரிய திட்டம் தன் வழியில் நடக்கும்போது, ஒரு கருவியாக (நிமித்தமாக) இருந்து தன் கடமையைச் செய்யுமாறு அவனிடம் சொல்லப்படுகிறது."], "Gita 12.13": ["கீதை 12.13", "உண்மையான பக்தனின் இலக்கணம்", "எந்த உயிரையும் வெறுக்காதவன், அனைவருக்கும் நண்பனும் கருணையுள்ளவனும், 'எனது' என்ற பற்றும் அகங்காரமும் இல்லாதவன், இன்பதுன்பங்களில் சமமானவன், பொறுமையுள்ளவன்.", "பக்தியின் அளவுகோல் நீங்கள் எவ்வளவு நேரம் பூஜை செய்கிறீர்கள் என்பதல்ல, பிறரிடம் எப்படி நடந்துகொள்கிறீர்கள் என்பதே. வெறுப்பின்மை, நட்பு, கருணை, பணிவு, பொறுமை, இவையே உண்மையான பக்தனின் அடையாளம்."], "Gita 12.15": ["கீதை 12.15", "யாரையும் கலங்கடிக்காதவன், தானும் கலங்காதவன்", "யாரால் உலக மக்கள் கலங்குவதில்லையோ, தானும் உலகத்தால் கலங்காதவனோ, களிப்பு, பொறாமை, பயம், பதற்றம் ஆகியவற்றிலிருந்து விடுபட்டவனோ, அவன் எனக்குப் பிரியமானவன்.", "அன்றாட எளிய சோதனை: மக்கள் உங்கள் அருகில் இயல்பாக உணர்கிறார்களா? பிறர் கடினமாக நடந்தாலும் நீங்கள் அமைதியாக இருக்கிறீர்களா? இரண்டையும் பயிற்சி செய்யுங்கள்."], "Gita 13.2": ["கீதை 13.2", "ஒவ்வொரு க்ஷேத்ரத்திலும் க்ஷேத்ரக்ஞன் நானே", "ஓ பாரதா! எல்லா க்ஷேத்ரங்களிலும் (உடல்களிலும்) க்ஷேத்ரக்ஞனும் நானே என்று அறி. க்ஷேத்ரம், க்ஷேத்ரக்ஞன் பற்றிய அறிவே என் கருத்தில் உண்மையான ஞானம்.", "உங்களிடம் உடல் உள்ளது, ஆனால் நீங்கள் உடலை அறிபவர். \"என்னிடம் என்ன உள்ளது\" என்பதையும் \"நான் யார்\" என்பதையும் பிரித்தறிவதே ஆன்மீக ஞானத்தின் சாரம். (சில பதிப்புகளில் இந்த ஸ்லோகம் 13.3.)"], "Gita 13.27": ["கீதை 13.27", "யஃ பச்யதி ஸ பச்யதி", "அழியும் எல்லா உயிர்களிலும் சமமாக நிலைத்திருக்கும், ஒருபோதும் அழியாத பரமேஸ்வரனைக் காண்பவனே உண்மையில் காண்கிறான்.", "கண்கள் பிறந்து இறக்கும் உடல்களைக் காண்கின்றன. ஞானம் ஒவ்வொரு உடலிலும் அதே நித்தியமான இருப்பைக் காண்கிறது. இதுவே உண்மையான பார்வை. (சில பதிப்புகளில் 13.28.)"], "Gita 14.5": ["கீதை 14.5", "இயற்கையின் மூன்று குணங்கள்", "ஓ மகாபாஹு! இயற்கையிலிருந்து தோன்றிய சத்வம், ரஜஸ், தமஸ் என்ற இந்த மூன்று குணங்களும் அழிவற்ற ஆத்மாவை உடலில் கட்டுகின்றன.", "நன்மையும் இன்பத்தின் மீதும் அறிவின் மீதும் உள்ள பற்றால் கட்டலாம். முதலில் தமஸிலிருந்து ரஜஸுக்கு நகருங்கள் (சுறுசுறுப்பாகுங்கள்), பிறகு ரஜஸிலிருந்து சத்வத்திற்கு (அமைதியும் தெளிவும் பெறுங்கள்), இறுதியில் மூன்றையும் கடந்து செல்லுங்கள்."], "Gita 15.1": ["கீதை 15.1", "ஊர்த்வமூல அஸ்வத்தம்", "மேலே வேர்களும் கீழே கிளைகளும் கொண்ட, வேதச் சந்தங்களை இலைகளாகக் கொண்ட அழியாத அஸ்வத்த மரம் ஒன்று உண்டு என்கின்றனர். அதை அறிபவனே வேதத்தை அறிந்தவன்.", "சாதாரண மரம் கீழே உள்ள மண்ணிலிருந்து உயிர் பெறுகிறது. இந்த உலகம் மேலே உள்ள பரமாத்மாவிடமிருந்து உயிர் பெறுகிறது. கிளைகளை (பொருட்களை) மட்டும் பிடித்துக்கொண்டிருந்தால், அவற்றுக்கு உயிர் தரும் வேரை மறந்துவிடுகிறோம்."], "Gita 15.7": ["கீதை 15.7", "மமைவாம்சோ ஜீவலோகே", "இந்த ஜீவலோகத்தில் ஜீவாத்மா என் சனாதனமான அம்சமே. அது இயற்கையில் உள்ள மனம் உட்பட ஆறு புலன்களைத் தன்னிடம் இழுக்கிறது.", "ஒவ்வொரு உயிரும் அதே தெய்வீக நெருப்பின் பொறி. இது ஒவ்வொருவருக்கும் கண்ணியம் தருகிறது, அனைவரையும் மதிப்பதற்கான காரணத்தையும் தருகிறது."], "Gita 16.1": ["கீதை 16.1", "தெய்வீகச் செல்வத்தின் குணங்கள்", "அச்சமின்மை, உள்ளத் தூய்மை, ஞானத்திலும் யோகத்திலும் உறுதியான நிலை, தானம், புலனடக்கம், யாகம், சுயகல்வி, தவம், நேர்மை...", "முதல் தெய்வீக குணம் அபயம் (அச்சமின்மை). இந்தப் பட்டியல் சடங்குகளுடையது அல்ல, ஒழுக்கத்துடையது என்பதைக் கவனியுங்கள். இதை வைத்து யார் வேண்டுமானாலும் தன்னை வளர்த்துக்கொள்ளலாம்."], "Gita 16.21": ["கீதை 16.21", "நரகத்தின் மூன்று வாயில்கள்", "காமம், கோபம், பேராசை ஆகிய இம்மூன்றும் ஆத்மாவை அழிக்கும் நரகத்தின் வாயில்கள். ஆகவே இம்மூன்றையும் துறக்க வேண்டும்.", "மனிதன் தனக்கும் பிறருக்கும் செய்யும் பெரும்பாலான தீங்கு இந்த மூன்று வாயில்கள் வழியாகவே வருகிறது. இந்த நரகத்தைக் காண மரணம் வரை காத்திருக்கத் தேவையில்லை; உடைந்த குடும்பங்களிலும் கடனிலும் வருத்தத்திலும் அது தெரிகிறது."], "Gita 17.3": ["கீதை 17.3", "யோ யச்ச்ரத்தஃ ஸ ஏவ ஸஃ", "ஓ பாரதா! அனைவரின் சிரத்தையும் அவரவர் உள்ளத்திற்கு ஏற்ப அமைகிறது. மனிதன் சிரத்தையால் ஆனவன்; யாருடைய சிரத்தை எப்படியோ, அவன் அப்படியே.", "நீங்கள் எதை ஆழமாக நம்புகிறீர்களோ, எதற்கு மதிப்பளிக்கிறீர்களோ, அதுவே உங்களை வடிவமைக்கிறது. எதில் சிரத்தை வைப்பது என்பதைச் சிந்தித்துத் தேர்ந்தெடுங்கள்."], "Gita 17.15": ["கீதை 17.15", "வாக்கின் தவம்", "யாரையும் கலங்கடிக்காத, உண்மையான, இனிய, நன்மை தரும் சொல்லும், அதனுடன் சுயகல்விப் பயிற்சியும், வாக்கின் தவம் எனப்படுகிறது.", "பேசும் முன் நான்கு கேள்விகள் கேளுங்கள்: இது உண்மையா? இது இனிமையானதா? இது நன்மை தருமா? இது யாரையாவது தேவையின்றிப் புண்படுத்துமா? இது நாள் முழுவதும் செய்யக்கூடிய சாதனை. (\"இனிய உளவாக இன்னாத கூறல் கனியிருப்பக் காய்கவர்ந் தற்று\" என்கிறார் வள்ளுவர்.)"], "Gita 18.66": ["கீதை 18.66", "மாமேகம் சரணம் வ்ரஜ", "எல்லா தர்மங்களையும் (கடமைகள் பற்றிய கவலையை) விட்டு என்னை மட்டும் சரணடை. நான் உன்னை எல்லாப் பாவங்களிலிருந்தும் விடுவிப்பேன். வருந்தாதே.", null], "Gita 18.78": ["கீதை 18.78", "யத்ர யோகேஸ்வரஃ கிருஷ்ணஃ", "எங்கே யோகேஸ்வரனான ஸ்ரீ கிருஷ்ணர் இருக்கிறாரோ, எங்கே வில்லேந்திய அர்ஜுனன் இருக்கிறானோ, அங்கேயே திருவும் வெற்றியும் ஐஸ்வர்யமும் நிலையான நீதியும் உள்ளன, இதுவே என் கருத்து.", "சஞ்சயன் சொல்லும் கீதையின் கடைசி ஸ்லோகம். ஸ்ரீ கிருஷ்ணர் தெய்வீக ஞானத்தின் சின்னம், அர்ஜுனன் மனித முயற்சியின் சின்னம். இரண்டும் சேர்ந்திருக்கும்போது வெற்றி கிடைக்கிறது: ஞானம் முயற்சிக்கு வழிகாட்ட வேண்டும்."], "Rigveda 10.121.1": ["ரிக்வேதம் 10.121.1", "ஹிரண்யகர்ப்ப சூக்தம்", "படைப்பின் தொடக்கத்தில் ஹிரண்யகர்ப்பன் தோன்றினான். பிறந்தவுடனேயே அவன் எல்லா உயிர்களுக்கும் ஒரே தலைவன். அவன் பூமியையும் இந்த வானத்தையும் தாங்கினான். நாம் எந்தத் தேவனை அவிசால் வழிபடுவோம்?", "பிரபஞ்சம் படைப்பு ஆற்றலின் ஒளிரும் ஒரு விதையிலிருந்து தொடங்குகிறது; இதே சித்திரம் பின்னர் புராணங்களில் பிரம்மாவின் பொன் முட்டையானது. ஒவ்வொரு மந்திரத்தின் இறுதியிலும் திரும்ப வரும் \"எந்தத் தேவனை?\" என்ற கேள்விக்குப் பதில் சூக்தத்தின் இறுதி மந்திரத்தில் கிடைக்கிறது: பிரஜாபதி, எல்லா உயிர்களின் தலைவன்."], "Rigveda 1.164.20": ["ரிக்வேதம் 1.164.20", "ஒரு மரத்தில் இரண்டு பறவைகள்", "அழகிய சிறகுகளுடைய இரண்டு பறவைகள், சேர்ந்திருக்கும் நண்பர்கள், ஒரே மரத்தில் அமர்ந்திருக்கின்றன. அவற்றில் ஒன்று சுவையான பழத்தை உண்கிறது; மற்றொன்று உண்ணாமல் வெறுமனே பார்த்துக்கொண்டிருக்கிறது.", "மரம் உடல். பழத்தை உண்ணும் பறவை ஜீவாத்மா, வாழ்க்கையின் இனிப்பும் கசப்புமான பழங்களைச் சுவைக்கிறது. பார்க்கும் பறவை பரமாத்மா, எப்போதும் அமைதியானது. முண்டக, ஸ்வேதாஸ்வதர உபநிடதங்கள் இந்த மந்திரத்தைத் திரும்பச் சொல்கின்றன: முதல் பறவை திரும்பி இரண்டாவதைப் பார்க்கும்போது, அதன் துயரம் நீங்குகிறது."], "Rigveda 10.75.5": ["ரிக்வேதம் 10.75.5", "நதி சூக்தம்", "கங்கையே, யமுனையே, சரஸ்வதியே, சுதுத்ரியே! பருஷ்ணியுடன் என் இந்தத் துதியை ஏற்றுக்கொள்ளுங்கள். மருத்விருதையே, அசிக்னியுடன்; ஆர்ஜீகீயையே, விதஸ்தா, சுஷோமையுடன், கேளுங்கள்!", "வடமேற்கு இந்தியாவின் நதிகளின் பட்டியல், கிழக்கிலிருந்து மேற்காக. பல இன்றும் அடையாளம் காணப்படுகின்றன: சுதுத்ரி சட்லஜ், பருஷ்ணி ராவி, அசிக்னி செனாப், விதஸ்தா ஜீலம். அதனால்தான் நீராடும்போது மக்கள் இந்த நதிகளை அழைக்கிறார்கள்: \"கங்கே ச யமுனே சைவ...\""], "Rigveda 10.117.6 (last line)": ["ரிக்வேதம் 10.117.6 (இறுதி வரி)", "தனியாக உண்பவன்", "தனியாக உண்பவன் தனியாகவே பாவத்துக்குப் பங்காளியாகிறான்.", "இந்த முழுச் சூக்தமும் (10.117) தானத்தைப் புகழ்கிறது: பகிரப்படாத செல்வம் வீண், தன் வயிற்றை மட்டும் நிரப்புபவன் உண்மையில் வாழ்வதில்லை. கீதையும் (3.13) இதையே சொல்கிறது: தங்களுக்காக மட்டுமே சமைப்பவர்கள் பாவத்தை உண்கிறார்கள்."], "Rigveda 10.191.4": ["ரிக்வேதம் 10.191.4", "இறுதி மந்திரம்: ஒரே இதயம், ஒரே மனம்", "உங்கள் எண்ணங்கள் சமமாக இருக்கட்டும், உங்கள் இதயங்கள் ஒன்றாக இருக்கட்டும். உங்கள் மனங்கள் ஒன்றுபோல் இருக்கட்டும், அதனால் நீங்கள் அனைவரும் சேர்ந்து மகிழ்ச்சியாக வாழலாம்.", "அக்னி துதியுடன் தொடங்கிய ரிக்வேதம் மக்களின் ஒற்றுமைக்கான பிரார்த்தனையுடன் முடிகிறது. இந்தியாவில் பல குடும்பங்களும் பள்ளிகளும் அமைப்புகளும் கூட்டத்தின் இறுதியில் இந்த மந்திரத்தை ஓதுகின்றன."], "Shukla Yajurveda 36.17": ["சுக்ல யஜுர்வேதம் 36.17", "சாந்தி பாடம்", "த்யுலோகத்தில் அமைதி நிலவட்டும், அந்தரிக்ஷத்தில் அமைதி நிலவட்டும், பூமியில் அமைதி நிலவட்டும். நீரில், மூலிகைகளில், தாவரங்களில் அமைதி நிலவட்டும். எல்லாத் தேவர்களிலும், பிரம்மத்திலும், எல்லாவற்றிலும் அமைதி நிலவட்டும். அமைதியும் அமைதியாக இருக்கட்டும். அந்த அமைதி எனக்குக் கிடைக்கட்டும்.", "பிரார்த்தனை வானத்தில் தொடங்கிப் பூமி, நீர், தாவரங்கள் வரை வருகிறது, கடைசியில் தனக்காக அமைதியைக் கேட்கிறது. உள் அமைதி இயற்கையின், சமூகத்தின் அமைதியுடன் இணைந்தது. இது ஏறக்குறைய ஒவ்வொரு இந்துச் சடங்கின் இறுதியிலும் ஓதப்படுகிறது."], "Shukla Yajurveda 40.2 (Isha Upanishad 2)": ["சுக்ல யஜுர்வேதம் 40.2 (ஈசோபநிடதம் 2)", "செயல்பட்டுக்கொண்டே நூறு ஆண்டுகள் வாழ்", "இந்த உலகில் செயல்பட்டுக்கொண்டே நூறு ஆண்டுகள் வாழ விரும்பு. உனக்கு இதைத் தவிர வேறு வழி இல்லை. இவ்வாறு செய்த செயல் மனிதனைக் கட்டுவதில்லை.", "வேதங்கள் வாழ்க்கையிலிருந்து ஓடச் சொல்வதில்லை. நீண்ட காலம் வாழ், சுறுசுறுப்பாக இரு, ஆனால் முதல் மந்திரத்தின் உணர்வுடன் வேலை செய்: எல்லாம் இறைவனுடையது, பேராசையின்றி. இதுவே கீதையின் கர்மயோகத்தின் விதை."], "Shukla Yajurveda 36.24": ["சுக்ல யஜுர்வேதம் 36.24", "பச்யேம சரத: சதம்", "தேவர்களுக்கு நன்மை செய்யும் அந்த ஒளிரும் கண் (சூரியன்) கிழக்கில் உதிக்கிறது. நாம் நூறு சரத் காலங்கள் காண்போம், நூறு ஆண்டுகள் வாழ்வோம், நூறு ஆண்டுகள் கேட்போம், நூறு ஆண்டுகள் பேசுவோம், நூறு ஆண்டுகள் யாரையும் சார்ந்திருக்காமல் இருப்போம், நூறுக்கும் மேலாகவும்.", "உதிக்கும் சூரியனிடம் நீண்ட, ஆரோக்கியமான, தற்சார்புடைய வாழ்க்கைக்கான பிரார்த்தனை: நல்ல கண்கள், நல்ல காதுகள், தெளிவான பேச்சு, முதுமையிலும் மாண்பு. இது பெரும்பாலும் பிறந்தநாளில் ஓதப்படுகிறது."], "Shukla Yajurveda 34.1": ["சுக்ல யஜுர்வேதம் 34.1", "சிவசங்கல்ப சூக்தம்", "விழித்திருக்கும்போது தொலைதூரம் செல்லும், உறங்கும்போதும் அப்படியே செல்லும், தொலைவு செல்லும், ஒளிகளின் ஒளியான அந்தத் தெய்வீக என் மனம் நல்ல எண்ணங்களுடையதாக இருக்கட்டும்.", null], "Shukla Yajurveda 16.1 (Rudram)": ["சுக்ல யஜுர்வேதம் 16.1 (ருத்ராத்யாயம்)", "நமஸ்தே ருத்ர", "ருத்ரரே! உம் சினத்துக்கு வணக்கம், உம் அம்புக்கு வணக்கம். உம் இரு கைகளுக்கும் வணக்கம்.", null], "Taittiriya Upanishad 1.11 (Krishna Yajurveda)": ["தைத்திரீய உபநிடதம் 1.11 (கிருஷ்ண யஜுர்வேதம்)", "பட்டமளிப்பு உபதேசம்", "உண்மை பேசு. தர்மத்தைக் கடைப்பிடி. சுவாத்தியாயத்தில் சோம்பல் கொள்ளாதே. ... தாயைத் தெய்வமாகக் கருது. தந்தையைத் தெய்வமாகக் கருது. ஆசாரியரைத் தெய்வமாகக் கருது. விருந்தினரைத் தெய்வமாகக் கருது.", "வேத ஆசாரியர்கள் சீடர்கள் கல்வியை முடித்து இல்லற வாழ்க்கைக்குச் செல்லும்போது அளித்த உபதேசம் இது. இன்றும் இது பட்டமளிப்பு விழாக்களில் ஓதப்படுகிறது, \"அதிதி தேவோ பவ\" இந்தியச் சுற்றுலாவின் குறிக்கோள் வாசகம்."], "Chandogya Upanishad 1.1.1": ["சாந்தோக்ய உபநிடதம் 1.1.1", "ஓம் வழிபாடு", "\"ஓம்\" என்ற இந்த எழுத்தை உத்கீதமாக வழிபட வேண்டும், ஏனெனில் உத்காதா \"ஓம்\" என்று சொல்லியே பாடத் தொடங்குகிறார். இப்போது அதன் விளக்கம்.", "பாடகர்களின் இந்த உபநிடதம் ஒவ்வொரு பாடலும் தொடங்கும் அதே ஒலியுடன் தொடங்குகிறது. ஓம் எல்லாப் பேச்சின், எல்லா இசையின், எல்லா வேதங்களின் சாரமாகக் கருதப்படுகிறது. அதனால்தான் ஏறக்குறைய ஒவ்வொரு மந்திரமும் ஓம் என்று தொடங்குகிறது."], "Chandogya Upanishad 3.14.1": ["சாந்தோக்ய உபநிடதம் 3.14.1", "சர்வம் கல்விதம் பிரம்ம", "இவை அனைத்தும் உண்மையில் பிரம்மமே. அனைத்தும் அதிலிருந்தே பிறக்கின்றன, அதிலேயே ஒடுங்குகின்றன, அதிலேயே வாழ்கின்றன (தஜ்ஜலான்). இவ்வாறு அறிந்து அமைதியான மனதுடன் அதை வழிபடு.", null], "Chandogya Upanishad 6.8.7": ["சாந்தோக்ய உபநிடதம் 6.8.7", "தத்வமஸி", "அந்த மிக நுட்பமான சாரம் எதுவோ, இந்த முழு உலகமும் அதையே ஆத்மாவாகக் கொண்டுள்ளது. அதுவே சத்தியம், அதுவே ஆத்மா. ஸ்வேதகேதுவே, நீ அதுவே.", "பன்னிரண்டு ஆண்டுகள் கற்று இளைஞன் ஸ்வேதகேது கர்வத்துடன் வீடு திரும்பினான். தந்தை உத்தாலகர் அவனிடம் ஆலமர விதையை உடைக்கச் சொன்னார்: \"என்ன தெரிகிறது?\" \"ஒன்றுமில்லை.\" \"அந்தக் கண்ணுக்குத் தெரியாத சாரத்திலிருந்தே இந்தப் பெரிய மரம் வளர்கிறது. அந்த நுட்பமான சாரமே அனைவரின் ஆத்மா, நீ அதுவே.\" நீரில் கரைந்த உப்பு போன்ற எளிய உதாரணங்களுடன் தந்தை இந்தப் போதனையை ஒன்பது முறை திரும்பச் சொல்கிறார்."], "Chandogya Upanishad 7.23.1": ["சாந்தோக்ய உபநிடதம் 7.23.1", "பூமாவே சுகம்", "எது பூமா (முடிவற்றது, பரந்தது)வோ, அதுவே சுகம். அல்பத்தில் (சிறிய, எல்லைக்குட்பட்டதில்) சுகம் இல்லை. பூமாவே சுகம்.", "எல்லா வித்யைகளையும் கற்றும் நாரதர் துயரத்துடன் இருந்தார். எந்த எல்லைக்குட்பட்ட பொருளும், செல்வமோ புகழோ சொத்தோ, நம்மை நீண்ட காலம் திருப்திப்படுத்த முடியாது என்று சனத்குமாரர் சொல்கிறார், ஏனெனில் நமக்கு எப்போதும் இன்னும் வேண்டும். முடிவற்றது மட்டுமே இதயத்தை நிரப்ப முடியும்."], "Kena Upanishad 1.1": ["கேன உபநிடதம் 1.1", "எதனால்?", "யாருடைய தூண்டுதலால் மனம் தன் பொருள்களை நோக்கிச் செல்கிறது? எதனால் முதல் பிராணன் இயங்குகிறது? யாருடைய தூண்டுதலால் நாம் இந்தப் பேச்சைப் பேசுகிறோம்? எந்தத் தேவன் கண்ணையும் காதையும் வேலையில் ஈடுபடுத்துகிறான்?", null], "Atharvaveda 12.1.1": ["அதர்வவேதம் 12.1.1", "பூமியைத் தாங்குவது எது (பூமி சூக்தம்)", "பெரும் சத்தியம், உக்கிரமான ரிதம் (இயற்கை விதி), தீட்சை, தவம், பிரம்மம் (ஞானம்/பிரார்த்தனை), யக்ஞம், இவை பூமியைத் தாங்குகின்றன. கடந்த காலத்துக்கும் எதிர்காலத்துக்கும் தலைவியான அந்தப் பூமி நமக்குப் பரந்த இடத்தைத் தரட்டும்.", "பூமியை எந்த யானையோ ஆமையோ அல்ல, மதிப்பீடுகளே தாங்குகின்றன என்று இந்த மந்திரம் சொல்கிறது: சத்தியம், இயற்கை விதி, அர்ப்பணிப்பு, தன்னடக்கம். மக்கள் இவற்றைக் கைவிடும்போது உலகம் நிலையற்றதாகிறது."], "Atharvaveda 3.30.1 and 3.30.3": ["அதர்வவேதம் 3.30.1, 3.30.3", "குடும்ப ஒற்றுமைச் சூக்தம்", "நான் உங்களை ஒரே இதயமுடையவர்களாக, ஒரே மனமுடையவர்களாக, வெறுப்பற்றவர்களாக ஆக்குகிறேன். பசு தன் புதிதாகப் பிறந்த கன்றை நேசிப்பது போல ஒருவரையொருவர் நேசியுங்கள். சகோதரன் சகோதரனை வெறுக்கக் கூடாது, சகோதரி சகோதரியை வெறுக்கக் கூடாது. சேர்ந்து, ஒரே உறுதியுடன், ஒருவருக்கொருவர் இனிமையாகப் பேசுங்கள்.", "மூவாயிரம் ஆண்டுகள் பழமையானது, இருந்தும் குடும்பத்துக்குச் சிறந்த அறிவுரை: நிபந்தனையற்ற அன்பு, உடன்பிறந்தோரிடையே வெறுப்பின்மை, பொது இலக்கு, இனிய சொல். புதிதாகப் பிறந்த கன்றை நக்கும் பசுவின் சித்திரம் சுயநலமற்ற அன்பைக் காட்டுகிறது."], "Atharvaveda 19.15.6": ["அதர்வவேதம் 19.15.6", "அச்சமின்மைக்கான பிரார்த்தனை", "எங்களுக்கு நண்பனிடமிருந்து அச்சமின்மை, எதிரியிடமிருந்து அச்சமின்மை, அறிந்ததிலிருந்து அச்சமின்மை, அறியாததிலிருந்து அச்சமின்மை கிடைக்கட்டும். இரவில் அச்சமின்மை, பகலில் அச்சமின்மை கிடைக்கட்டும். எல்லாத் திசைகளும் என் நண்பர்களாக இருக்கட்டும்.", "மனம் பதறும்போது சொல்ல ஒரு சிறிய பிரார்த்தனை. அச்சம் பல பக்கங்களிலிருந்து வருகிறது, தெரிந்த மனிதர்களிடமிருந்தும், கண்ணுக்குத் தெரியாதவற்றிலிருந்தும். முழு உலகமும் நண்பனைப் போலத் தோன்ற வேண்டும் என்ற விருப்பத்துடன் பிரார்த்தனை முடிகிறது."], "Mundaka Upanishad 3.1.6": ["முண்டக உபநிடதம் 3.1.6", "சத்யமேவ ஜயதே", "சத்தியமே வெல்கிறது, பொய் அல்ல. சத்தியத்தாலேயே தேவர்களின் பாதை (தேவயானம்) அமைக்கப்பட்டுள்ளது.", "அதர்வவேத உபநிடதத்தின் இந்த வரி இந்தியாவின் தேசியக் குறிக்கோள் வாசகம், ஒவ்வொரு ரூபாய் நோட்டிலும் அரசு முத்திரையிலும் அசோகத் தூணுக்குக் கீழே எழுதப்பட்டுள்ளது."], "Mandukya Upanishad 1": ["மாண்டூக்ய உபநிடதம் 1", "சர்வமோங்கார ஏவ", "ஓம், இந்த எழுத்தே இவை அனைத்தும். இது அதன் விளக்கம்: கடந்த காலம், நிகழ்காலம், எதிர்காலம், எல்லாம் ஓங்காரமே.", "மிகச் சிறிய முதன்மை உபநிடதமான மாண்டூக்யம், ஓம் என்பதன் மூன்று ஒலிகளால் உணர்வின் மூன்று நிலைகளை விளக்குகிறது, ஓம் பிறகான மௌனத்தால் ஆத்மாவைச் சுட்டிக்காட்டுகிறது. கீழே உள்ள படத்தைப் பாருங்கள்."], "Isha Upanishad 9": ["ஈசாவாஸ்ய உபநிடதம் 9", "வெறும் வித்யையோ வெறும் அவித்யையோ அல்ல", "வெறும் அவித்யையை (உலகச் செயல்களை) வழிபடுபவர்கள் கடும் இருளில் புகுகிறார்கள். வெறும் வித்யையிலேயே (ஞானத்திலேயே) மகிழ்ந்திருப்பவர்கள் அதை விடவும் அதிக இருளுக்குச் செல்வது போல.", "ஒரு வியக்கவைக்கும் மந்திரம்: ஆன்மீக அறிவும், வாழ்க்கையிலிருந்தும் கடமையிலிருந்தும் துண்டிக்கப்பட்டால், பந்தமாகிவிடுகிறது. அடுத்த மந்திரங்கள் இரண்டும் தேவை என்கின்றன: நல்ல வாழ்க்கைக்கு உலகத் திறமை, மரணத்தைக் கடக்க ஆன்மீக அறிவு."], "Katha Upanishad 1.2.2": ["கடோபநிடதம் 1.2.2", "சிரேயஸும் பிரேயஸும்", "சிரேயஸ் (நன்மை தருவது), பிரேயஸ் (இனிமையாகத் தோன்றுவது), இரண்டும் மனிதன் முன் வருகின்றன. தீரன் இரண்டையும் ஆராய்ந்து பிரித்தறிகிறான். தீரன் பிரேயஸை விடச் சிரேயஸைத் தேர்ந்தெடுக்கிறான்; மந்த அறிவுடையவன் பேராசையாலும் பற்றாலும் பிரேயஸைத் தேர்ந்தெடுக்கிறான்.", "ஒவ்வொரு நாளும் நாம் தேர்ந்தெடுக்கிறோம், இப்போது நன்றாகத் தோன்றுவதையா, அல்லது உண்மையில் நமக்கு நல்லதையா: போனா அல்லது படிப்பா, துரித உணவா அல்லது சத்தான உணவா, கோபமா அல்லது பொறுமையா. நசிகேதன் ஒவ்வொரு இன்பத்தையும் விடச் சிரேயஸையே தேர்ந்தெடுத்தான், அதனால்தான் அவன் உயர்ந்த ஞானத்துக்குத் தகுதியானான்."], "Katha Upanishad 1.3.3–4": ["கடோபநிடதம் 1.3.3–4", "வாழ்க்கையின் தேர்", "ஆத்மாவைத் தேரின் உரிமையாளனாகவும், உடலைத் தேராகவும் அறி. அறிவைத் தேரோட்டியாகவும், மனதைக் கடிவாளமாகவும் அறி. புலன்களைக் குதிரைகள் என்கிறார்கள், பொருள்கள் அவை செல்லும் பாதைகள்.", "இது இந்தியச் சிந்தனையின் மிகப் புகழ்பெற்ற சித்திரங்களில் ஒன்று. தெளிவான அறிவு மனதை நிலையாக வைத்திருக்கும்போது, புலன்கள் சரியான பாதையில் செல்கின்றன, பயணம் இலக்கை அடைகிறது. கீழே படத்தைப் பாருங்கள்."], "Mundaka Upanishad 1.1.4": ["முண்டக உபநிடதம் 1.1.4", "இரண்டு வகை அறிவு", "பிரம்மத்தை அறிந்தவர்கள் இரண்டு அறிவுகள் அறியத்தக்கவை என்கிறார்கள்: பரா (உயர்ந்தது), அபரா (தாழ்ந்தது).", "அபரா வித்யை என்பது உலகைப் பற்றி நாம் கற்பவை அனைத்தும்: மொழிகள், அறிவியல், தகவலாக சாஸ்திரங்களும் கூட. பரா வித்யை ஆத்மாவின் நேரடி அனுபவம். இரண்டுக்கும் முக்கியத்துவம் உண்டு, ஆனால் துயரத்தின் முடிவு இரண்டாவதால் மட்டுமே."], "Taittiriya Upanishad 2.1": ["தைத்திரீய உபநிடதம் 2.1", "சத்யம் ஞானமனந்தம் பிரம்ம", "பிரம்மம் சத்தியம், ஞானம், முடிவற்றது.", null], "Brihadaranyaka Upanishad 2.4.5": ["பிருஹதாரண்யக உபநிடதம் 2.4.5", "ஆத்மனஸ்து காமாய", "அன்பே! கணவன், கணவனுக்காகப் பிரியமானவன் அல்ல; ஆத்மாவுக்காகவே கணவன் பிரியமானவனாகிறான்.", "யாக்ஞவல்க்யர் மேலும் சொல்கிறார்: மனைவி, மகன், செல்வம், தேவர்கள், முழு உலகம், அனைத்தும் ஆத்மாவின் காரணமாகவே பிரியமானவை. யார் மீதான நம் அன்பும் உண்மையில் ஒரே ஆத்மா மற்றொருவரில் தன்னை அடையாளம் காண்பதே. ஆகவே, அவர் சொல்கிறார், ஆத்மாவையே காண வேண்டும், கேட்க வேண்டும், சிந்திக்க வேண்டும், தியானிக்க வேண்டும் (சிரவணம், மனனம், நிதித்யாசனம்)."], "Brihadaranyaka Upanishad 5.2.3": ["பிருஹதாரண்யக உபநிடதம் 5.2.3", "த த த: இடி முழக்கத்தின் உபதேசம்", "இதே விஷயத்தைத் தெய்வீகக் குரலான இடி முழக்கம் திரும்பச் சொல்கிறது: \"த! த! த!\" அடக்குங்கள் (தன்னடக்கம் கொள்ளுங்கள்), தானம் செய்யுங்கள், இரக்கம் காட்டுங்கள்.", null], "Shvetashvatara Upanishad 2.5": ["ஸ்வேதாஸ்வதர உபநிடதம் 2.5", "அம்ருதஸ்ய புத்ரா:", "கேளுங்கள், அமிர்தத்தின் மக்கள் அனைவரும், தெய்வீக உலகங்களில் வாழும் நீங்களும்!", "சுவாமி விவேகானந்தர் 1893 இல் சிகாகோ உலக சமய மாநாட்டில் இந்த மந்திரத்தை மேற்கோள் காட்டிச் சொன்னார்: நீங்கள் பாவிகள் அல்ல, அமிர்தத்தின் மக்கள். ஒவ்வொரு மனிதனிடமும் தெய்வீக மாண்பு உள்ளது."], "Ramayana, Bala Kanda 2.15": ["ராமாயணம், பால காண்டம் 2.15", "முதல் சுலோகம்", "நிஷாதனே! உனக்கு முடிவற்ற ஆண்டுகள் வரை பெருமை (அமைதி) கிடைக்காமல் போகட்டும், ஏனெனில் காதலில் மூழ்கிய கிரௌஞ்சப் பறவை இணையில் ஒன்றை நீ கொன்றாய்.", null], "Ramayana, Aranya Kanda (Maricha's words)": ["ராமாயணம், ஆரண்ய காண்டம் (மாரீசனின் சொற்கள்)", "ராமோ விக்ரஹவான் தர்ம:", "ராமன் தர்மத்தின் உருவம்.", "கவனிக்க வேண்டியது, இந்தப் புகழ்ச்சி ராமனின் எதிரியான அரக்கன் மாரீசனின் வாயிலிருந்து வருகிறது, ராமனுடன் போரிட வேண்டாம் என்று அவன் ராவணனை எச்சரிக்கும்போது. எதிரிகளும் அவருடைய நன்மையை உணர்ந்திருந்தார்கள்."], "Mahabharata, Vana Parva (Yaksha Prashna)": ["மகாபாரதம், வன பருவம் (யக்ஷப் பிரச்னம்)", "மிகப் பெரிய அதிசயம்", "ஒவ்வொரு நாளும் உயிர்கள் யமலோகத்துக்குச் செல்கின்றன. இருந்தும் எஞ்சியவர்கள் என்றும் வாழ விரும்புகிறார்கள். இதை விடப் பெரிய அதிசயம் என்ன?", "நான்கு பாண்டவர்கள் யக்ஷனின் கேள்விகளுக்குப் பதில் சொல்லாமல் ஏரியின் நீரைக் குடித்து இறந்து விழுந்தார்கள். யுதிஷ்டிரன் ஒவ்வொரு கேள்விக்கும் பதில் சொன்னான். \"மிகப் பெரிய அதிசயம் எது?\" என்று கேட்டபோது அவன் இந்தப் பதிலைச் சொன்னான். மகிழ்ந்த யக்ஷன் (தானே தர்மராஜன், அவன் தந்தை) அவன் சகோதரர்களை உயிர்ப்பித்தான். நாம் அனைவரும் இறப்போம் என்று அறிவோம், இருந்தும் ஒருபோதும் இறக்க மாட்டோம் என்பது போல வாழ்கிறோம்."], "Mahabharata, Anushasana Parva": ["மகாபாரதம், அனுசாசன பருவம்", "அஹிம்சா பரமோ தர்ம:", "அஹிம்சையே மிக உயர்ந்த தர்மம்.", "இந்த வாக்கியம் மகாபாரதத்தில் பலமுறை வருகிறது, மகாத்மா காந்திக்கு உத்வேகம் அளித்தது. பெரும் போரை விவரிக்கும் இதே நூல் யாருக்கும் தீங்கு செய்யாமையே உயர்ந்த மதிப்பு என்று கற்பிக்கிறது. ஒவ்வொரு அமைதியான முயற்சியும் தோல்வியுற்றபோது, இறுதி வழியாக மட்டுமே போர் அனுமதிக்கப்பட்டது."], "Devi Mahatmya 5 (Markandeya Purana)": ["தேவீ மாஹாத்மியம் 5 (மார்க்கண்டேய புராணம்)", "யா தேவீ சர்வபூதேஷு", "எந்தத் தேவி எல்லா உயிர்களிலும் சக்தியின் வடிவில் நிலைத்திருக்கிறாளோ, அவளுக்கு வணக்கம், அவளுக்கு வணக்கம், அவளுக்கு மீண்டும் மீண்டும் வணக்கம்.", "தேவீ மாஹாத்மியத்தில் இந்த மந்திரம் மீண்டும் மீண்டும் வருகிறது, ஒவ்வொரு முறையும் புதிய குணத்துடன்: தேவி உணர்வு, அறிவு, உறக்கம், பசி, பொறுமை, அமைதி, சிரத்தை, லக்ஷ்மி, இரக்கம், தாய் வடிவில். நம்மிடமுள்ள ஒவ்வொரு நல்ல குணமும் ஜகன்மாதாவின் வடிவமே. நவராத்திரியில் இது சிறப்பாக ஓதப்படுகிறது."], "Bhagavata Purana 1.3.28": ["பாகவத புராணம் 1.3.28", "கிருஷ்ணஸ்து பகவான் ஸ்வயம்", "இவை அனைத்தும் பரம புருஷனின் அம்சங்களும் கலைகளும், ஆனால் கிருஷ்ணர் தானே பகவான். உலகம் தேவர்களின் எதிரிகளால் துன்புறும்போது, இவர்கள் யுகந்தோறும் அதற்குச் சுகம் தருகிறார்கள்.", "அவதாரங்களின் பட்டியலைத் தந்த பிறகு பாகவதம் கிருஷ்ணரை இறைவனின் முழு வடிவமாகச் சொல்கிறது. இந்தச் சுலோகம் சைதன்ய சம்பிரதாயம், இஸ்கான் போன்ற கிருஷ்ண பக்தி மரபுகளின் மையத்தில் உள்ளது."], "Gita 1.2": ["கீதை 1.2", "1.2 · சஞ்சயன்", "சஞ்சயன் சொன்னார்: அணிவகுத்து நின்ற பாண்டவப் படையைக் கண்டு, அரசன் துரியோதனன் தன் ஆசாரியர் துரோணரிடம் சென்று இவ்வாறு சொன்னான்:", null], "Gita 1.3": ["கீதை 1.3", "1.3 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "ஆசாரியரே! உங்கள் அறிவாளிச் சீடனான துருபதனின் மகன் அணிவகுத்த, பாண்டுவின் மகன்களின் இந்தப் பெரும் படையைப் பாருங்கள்.", null], "Gita 1.4": ["கீதை 1.4", "1.4 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "இதில் போரில் பீமனுக்கும் அர்ஜுனனுக்கும் நிகரான பெரும் வில்லாளி வீரர்கள் இருக்கிறார்கள்: யுயுதானன், விராடன், மகாரதனான துருபதன்;", null], "Gita 1.5": ["கீதை 1.5", "1.5 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "திருஷ்டகேது, சேகிதானன், வலிமைமிக்க காசி மன்னன்; புருஜித், குந்திபோஜன், மனிதர்களில் சிறந்த சைப்யன்;", null], "Gita 1.6": ["கீதை 1.6", "1.6 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "வலிமைமிக்க யுதாமன்யு, வீரன் உத்தமௌஜா, சுபத்திரையின் மகன் அபிமன்யு, திரௌபதியின் மகன்கள், இவர்கள் அனைவரும் மகாரதர்கள்.", null], "Gita 1.7": ["கீதை 1.7", "1.7 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "இருபிறப்பாளர்களில் சிறந்தவரே! இப்போது எங்கள் படையின் முக்கியத் தலைவர்களையும் அறிந்துகொள்ளுங்கள்; உங்கள் தகவலுக்காக அவர்களின் பெயர்களைச் சொல்கிறேன்.", null], "Gita 1.8": ["கீதை 1.8", "1.8 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "நீங்களே, பீஷ்மர், கர்ணன், போரில் வெற்றி பெறும் கிருபாசாரியர்; அஸ்வத்தாமா, விகர்ணன், சோமதத்தனின் மகன்.", null], "Gita 1.9": ["கீதை 1.9", "1.9 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "எனக்காக உயிரைக் கொடுக்கத் தயாரான இன்னும் பல வீரர்கள் இருக்கிறார்கள், பல ஆயுதங்களைத் தாங்கி, போரில் தேர்ந்தவர்கள்.", null], "Gita 1.10": ["கீதை 1.10", "1.10 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "பீஷ்மரால் காக்கப்படும் எங்கள் படை அளவற்றதாகத் தோன்றுகிறது, பீமனால் காக்கப்படும் அவர்கள் படை அளவானது. (சில உரையாசிரியர்கள் இதற்கு எதிர்ப் பொருள் சொல்கிறார்கள்: எங்கள் படை போதாது, அவர்களுடையது போதும்.)", null], "Gita 1.11": ["கீதை 1.11", "1.11 · துரியோதனன் (சஞ்சயன் விவரித்தது)", "ஆகவே நீங்கள் அனைவரும் அவரவர் முனையில் உறுதியாக நின்று எல்லா வகையிலும் பீஷ்மரையே காத்திடுங்கள்.", null], "Gita 1.12": ["கீதை 1.12", "1.12 · சஞ்சயன்", "துரியோதனனை மகிழ்விக்க, குரு வம்சத்தின் முதியவரும் பராக்கிரமம் மிக்கவருமான பாட்டனார் பீஷ்மர் சிங்கம் போல் கர்ஜித்து உரக்கச் சங்கு ஊதினார்.", null], "Gita 1.13": ["கீதை 1.13", "1.13 · சஞ்சயன்", "பிறகு சங்குகள், முரசுகள், மேளங்கள், மிருதங்கங்கள், கொம்புகள் ஒரே நேரத்தில் முழங்கின, அந்த ஒலி மிகப் பயங்கரமாக இருந்தது.", null], "Gita 1.14": ["கீதை 1.14", "1.14 · சஞ்சயன்", "அப்போது வெள்ளைக் குதிரைகள் பூட்டிய பெரிய தேரில் அமர்ந்திருந்த ஸ்ரீகிருஷ்ணரும் அர்ஜுனனும் தங்கள் தெய்வீகச் சங்குகளை ஊதினார்கள்.", null], "Gita 1.15": ["கீதை 1.15", "1.15 · சஞ்சயன்", "ஸ்ரீகிருஷ்ணர் பாஞ்சஜன்யத்தையும், அர்ஜுனன் தேவதத்தத்தையும், பயங்கரச் செயல்கள் புரியும் பீமன் பௌண்ட்ரம் என்ற பெரும் சங்கையும் ஊதினார்கள்.", null], "Gita 1.16": ["கீதை 1.16", "1.16 · சஞ்சயன்", "குந்தியின் மகன் மன்னன் யுதிஷ்டிரன் அனந்தவிஜயத்தையும், நகுலனும் சகாதேவனும் சுகோஷம், மணிபுஷ்பகம் என்ற சங்குகளையும் ஊதினார்கள்.", null], "Gita 1.17": ["கீதை 1.17", "1.17 · சஞ்சயன்", "சிறந்த வில்லாளியான காசி மன்னன், மகாரதன் சிகண்டி, திருஷ்டத்யும்னன், விராடன், வெல்ல முடியாத சாத்யகி,", null], "Gita 1.18": ["கீதை 1.18", "1.18 · சஞ்சயன்", "துருபதன், திரௌபதியின் மகன்கள், நீண்ட கைகளுடைய சுபத்திரையின் மகன், அனைவரும், மன்னரே! தங்கள் தங்கள் சங்குகளை ஊதினார்கள்.", null], "Gita 1.19": ["கீதை 1.19", "1.19 · சஞ்சயன்", "வானத்தையும் பூமியையும் எதிரொலிக்கச் செய்த அந்தப் பயங்கர ஒலி திருதராஷ்டிரனின் மகன்களின் இதயங்களை நடுங்கச் செய்தது.", null], "Gita 1.20": ["கீதை 1.20", "1.20 · சஞ்சயன்", "ஆயுதங்கள் ஏவப்படவிருந்த நேரத்தில், அனுமன் கொடியுடைய அர்ஜுனன் திருதராஷ்டிரனின் மகன்கள் நிற்பதைக் கண்டு வில்லை உயர்த்தினான்,", null], "Gita 1.21": ["கீதை 1.21", "1.21 · அர்ஜுனன்", "ஸ்ரீகிருஷ்ணரிடம் சொன்னான்: \"அச்யுதா! என் தேரை இரு படைகளுக்கும் நடுவில் நிறுத்துங்கள்,", null], "Gita 1.22": ["கீதை 1.22", "1.22 · அர்ஜுனன்", "போர் ஆசையுடன் இங்கே யார் நிற்கிறார்கள், இந்தப் போரில் நான் யார் யாருடன் போரிட வேண்டும் என்று நான் பார்க்க வேண்டும்.", null], "Gita 1.23": ["கீதை 1.23", "1.23 · அர்ஜுனன்", "தீய அறிவுடைய துரியோதனனுக்கு நன்மை செய்ய விரும்பி யார் யார் போர் புரிய வந்திருக்கிறார்கள் என்று நான் பார்க்க விரும்புகிறேன்.\"", null], "Gita 1.24": ["கீதை 1.24", "1.24 · சஞ்சயன்", "சஞ்சயன் சொன்னார்: அர்ஜுனன் இவ்வாறு சொன்னதும், ஸ்ரீகிருஷ்ணர் அந்தச் சிறந்த தேரை இரு படைகளுக்கும் நடுவில் கொண்டுசென்று நிறுத்தினார்,", null], "Gita 1.25": ["கீதை 1.25", "1.25 · சஞ்சயன்", "பீஷ்மர், துரோணர், எல்லா அரசர்களுக்கும் முன்னால், சொன்னார்: \"பார்த்தா! இங்கே ஒன்றுகூடிய இந்தக் கௌரவர்களைப் பார்.\"", null], "Gita 1.26": ["கீதை 1.26", "1.26 · சஞ்சயன்", "அங்கே அர்ஜுனன் இரு படைகளிலும் நின்ற தந்தைக்கு நிகரான பெரியவர்கள், பாட்டனார்கள், குருமார்கள், மாமன்கள், சகோதரர்கள், மகன்கள், பேரன்கள், நண்பர்களைக் கண்டான்,", null], "Gita 1.27": ["கீதை 1.27", "1.27 · சஞ்சயன்", "மாமனார்களையும் நலம் விரும்பிகளையும் கூட. இந்த உறவினர்கள் அனைவரும் நிற்பதைக் கண்டு,", null], "Gita 1.28": ["கீதை 1.28", "1.28 · அர்ஜுனன்", "அர்ஜுனன் ஆழ்ந்த கருணையால் நிறைந்து, துயருடன் சொன்னான்: \"கிருஷ்ணா! போரிட விரும்பும் என் சொந்த மக்களையே எதிரில் கண்டு,", null], "Gita 1.29": ["கீதை 1.29", "1.29 · அர்ஜுனன்", "என் உறுப்புகள் தளர்கின்றன, வாய் உலர்கிறது, உடல் நடுங்குகிறது, மயிர்க்கூச்செறிகிறது.", null], "Gita 1.30": ["கீதை 1.30", "1.30 · அர்ஜுனன்", "காண்டீபம் கையிலிருந்து நழுவுகிறது, தோல் எரிகிறது, என்னால் நிற்க முடியவில்லை, என் மனம் சுழல்கிறது.", null], "Gita 1.31": ["கீதை 1.31", "1.31 · அர்ஜுனன்", "கேசவா! எனக்குத் தீய சகுனங்கள் தெரிகின்றன, போரில் என் சொந்த மக்களையே கொல்வதில் எந்த நன்மையும் எனக்குத் தெரியவில்லை.", null], "Gita 1.32": ["கீதை 1.32", "1.32 · அர்ஜுனன்", "கிருஷ்ணா! நான் வெற்றியையோ, அரசையோ, சுகத்தையோ விரும்பவில்லை. கோவிந்தா! அத்தகைய அரசு, இன்பங்கள், வாழ்க்கையால் கூட எங்களுக்கு என்ன பயன்,", null], "Gita 1.33": ["கீதை 1.33", "1.33 · அர்ஜுனன்", "யாருக்காக நாங்கள் அரசையும் சுகத்தையும் விரும்புகிறோமோ, அவர்களே உயிர், செல்வம் மீதான ஆசையை விட்டுப் போரில் நிற்கும்போது?", null], "Gita 1.34": ["கீதை 1.34", "1.34 · அர்ஜுனன்", "குருமார்கள், தந்தைகள், மகன்கள், பாட்டனார்கள், மாமன்கள், மாமனார்கள், பேரன்கள், மைத்துனர்கள், பிற உறவினர்கள்.", null], "Gita 1.35": ["கீதை 1.35", "1.35 · அர்ஜுனன்", "மதுசூதனா! அவர்கள் என்னைக் கொன்றாலும் நான் அவர்களைக் கொல்ல விரும்பவில்லை, மூன்று உலகங்களின் அரசுக்காகக் கூட இல்லை, பூமியைப் பற்றிச் சொல்லவே வேண்டாம்.", null], "Gita 1.36": ["கீதை 1.36", "1.36 · அர்ஜுனன்", "ஜனார்த்தனா! திருதராஷ்டிரனின் மகன்களைக் கொன்று எங்களுக்கு என்ன சுகம் கிடைக்கும்? இந்த ஆததாயிகளைக் கொன்றால் எங்களுக்குப் பாவமே சேரும்.", null], "Gita 1.37": ["கீதை 1.37", "1.37 · அர்ஜுனன்", "ஆகவே எங்கள் உறவினர்களான திருதராஷ்டிரனின் மகன்களைக் கொல்வது எங்களுக்குத் தகாது. மாதவா! எங்கள் சொந்த மக்களையே கொன்று நாங்கள் எப்படி சுகமாக இருப்போம்?", null], "Gita 1.38": ["கீதை 1.38", "1.38 · அர்ஜுனன்", "பேராசையால் குருடான இவர்கள் குல அழிவில் உள்ள குற்றத்தையும், நண்பர்களுக்குத் துரோகம் செய்வதில் உள்ள பாவத்தையும் காணாவிட்டாலும்,", null], "Gita 1.39": ["கீதை 1.39", "1.39 · அர்ஜுனன்", "ஆனால் ஜனார்த்தனா! குல அழிவின் குற்றத்தைக் காணக்கூடிய நாங்கள் இந்தப் பாவத்திலிருந்து ஏன் விலகக் கூடாது?", null], "Gita 1.40": ["கீதை 1.40", "1.40 · அர்ஜுனன்", "குலம் அழிவதால் அதன் சனாதன மரபுகள் அழிந்துவிடுகின்றன; தர்மம் அழியும்போது அதர்மம் முழுக் குலத்தையும் சூழ்ந்துகொள்கிறது.", null], "Gita 1.41": ["கீதை 1.41", "1.41 · அர்ஜுனன்", "கிருஷ்ணா! அதர்மம் பெருகும்போது குலப் பெண்கள் வழிதவறுகிறார்கள், அதனால் வர்ணக் கலப்பு (சமூக ஒழுங்கில் குழப்பம்) உண்டாகிறது.", null], "Gita 1.42": ["கீதை 1.42", "1.42 · அர்ஜுனன்", "இந்த வர்ணக் கலப்பு குலத்தையும் குலத்தை அழிப்பவர்களையும் நரகத்திற்குக் கொண்டுசெல்கிறது; பிண்ட நீர்க்கடன்கள் கிடைக்காததால் அவர்களின் முன்னோர்களும் வீழ்கிறார்கள்.", null], "Gita 1.43": ["கீதை 1.43", "1.43 · அர்ஜுனன்", "குலத்தை அழிப்பவர்களின் இந்தக் குற்றங்களால் ஜாதி, குலங்களின் சனாதன தர்மங்கள் அழிந்துவிடுகின்றன.", null], "Gita 1.44": ["கீதை 1.44", "1.44 · அர்ஜுனன்", "ஜனார்த்தனா! யாருடைய குல தர்மங்கள் அழிகின்றனவோ அவர்கள் நீண்ட காலம் நரகத்தில் வசிக்கிறார்கள் என்று நாங்கள் கேட்டிருக்கிறோம்.", null], "Gita 1.45": ["கீதை 1.45", "1.45 · அர்ஜுனன்", "ஐயோ! அரசு சுகத்தின் மீதான பேராசையால் எங்கள் சொந்த மக்களையே கொல்லத் துணிந்து, எவ்வளவு பெரிய பாவம் செய்ய முனைந்திருக்கிறோம்!", null], "Gita 1.46": ["கீதை 1.46", "1.46 · அர்ஜுனன்", "நான் ஆயுதங்களைக் கைவிட்டு, எதிர்க்காமல் நின்று, ஆயுதம் ஏந்திய திருதராஷ்டிரனின் மகன்கள் என்னைப் போரில் கொன்றாலும் அதுவே எனக்கு நல்லது.\"", null], "Gita 1.47": ["கீதை 1.47", "1.47 · சஞ்சயன்", "சஞ்சயன் சொன்னார்: போர்க்களத்தில் இவ்வாறு சொல்லி, துயரத்தால் கலங்கிய மனமுடைய அர்ஜுனன் வில்லையும் அம்புகளையும் கைவிட்டுத் தேரின் பின்பகுதியில் அமர்ந்தான்.", null], "Gita 2.1": ["கீதை 2.1", "2.1 · சஞ்சயன்", "சஞ்சயன் சொன்னார்: கருணையால் நிறைந்து, கண்ணீர் நிறைந்த கண்களுடன் துயருற்ற அர்ஜுனனிடம் ஸ்ரீகிருஷ்ணர் இவ்வாறு சொன்னார்.", null], "Gita 2.2": ["கீதை 2.2", "2.2 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீபகவான் சொன்னார்: அர்ஜுனா! இந்த நெருக்கடியான நேரத்தில் இந்த மயக்கம் உனக்கு எங்கிருந்து வந்தது? இது சிறந்தோருக்குத் தகாது, சொர்க்கத்தையும் தராது, புகழையும் தராது.", null], "Gita 2.3": ["கீதை 2.3", "2.3 · ஸ்ரீகிருஷ்ணர்", "பார்த்தா! கோழைத்தனத்துக்கு அடிபணியாதே; இது உனக்குத் தகாது. இதயத்தின் இந்த அற்பப் பலவீனத்தை விட்டு எழுந்திரு, பரந்தபா!", null], "Gita 2.4": ["கீதை 2.4", "2.4 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: மதுசூதனா! போரில் பீஷ்மர் மீதும் துரோணர் மீதும் நான் எப்படி அம்பு எய்வேன்? அவர்கள் வணங்கத்தக்கவர்கள்.", null], "Gita 2.5": ["கீதை 2.5", "2.5 · அர்ஜுனன்", "இந்த மகான்களான குருமார்களைக் கொல்வதை விட இந்த உலகில் பிச்சை எடுத்து வாழ்வது மேல். இவர்களைக் கொன்றால் நான் இரத்தம் தோய்ந்த இன்பங்களையே அனுபவிப்பேன்.", null], "Gita 2.6": ["கீதை 2.6", "2.6 · அர்ஜுனன்", "எது நல்லது என்றும் எங்களுக்குத் தெரியாது: நாங்கள் அவர்களை வெல்வதா, அவர்கள் எங்களை வெல்வதா. எதிரில் திருதராஷ்டிரனின் மகன்கள் நிற்கிறார்கள், அவர்களைக் கொன்று நாங்கள் வாழ விரும்பவும் மாட்டோம்.", null], "Gita 2.7": ["கீதை 2.7", "2.7 · அர்ஜுனன்", "பலவீனமும் இரக்கமும் என் இயல்பை அடக்கிவிட்டன, தர்ம விஷயத்தில் என் மனம் குழம்பியிருக்கிறது. எனக்கு எது நன்மை என்று உறுதியாகச் சொல்லுங்கள். நான் உங்கள் சீடன், உங்களைச் சரணடைந்திருக்கிறேன், எனக்கு உபதேசியுங்கள்.", null], "Gita 2.8": ["கீதை 2.8", "2.8 · அர்ஜுனன்", "பூமியின் எதிரிகளற்ற, செழிப்பான அரசோ, தேவர்களின் ஆட்சியோ கிடைத்தாலும், புலன்களை வாட்டும் இந்தத் துயரத்தை நீக்கக்கூடியது எதுவும் எனக்குத் தெரியவில்லை.", null], "Gita 2.9": ["கீதை 2.9", "2.9 · சஞ்சயன்", "சஞ்சயன் சொன்னார்: ஸ்ரீகிருஷ்ணரிடம் இவ்வாறு சொல்லி அர்ஜுனன், \"கோவிந்தா! நான் போரிட மாட்டேன்\" என்று சொல்லி மௌனமானான்.", null], "Gita 2.10": ["கீதை 2.10", "2.10 · சஞ்சயன்", "அப்போது இரு படைகளுக்கும் நடுவில் துயரத்தில் மூழ்கிய அர்ஜுனனிடம் ஸ்ரீகிருஷ்ணர் புன்னகைப்பது போல இந்த வார்த்தைகளைச் சொன்னார்.", null], "Gita 2.11": ["கீதை 2.11", "2.11 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீபகவான் சொன்னார்: வருந்தத் தகாதவர்களுக்காக நீ வருந்துகிறாய், ஆனால் ஞானிகளைப் போலப் பேசுகிறாய். ஞானிகள் இறந்தவர்களுக்காகவும் வருந்துவதில்லை, உயிரோடிருப்பவர்களுக்காகவும் வருந்துவதில்லை.", null], "Gita 2.12": ["கீதை 2.12", "2.12 · ஸ்ரீகிருஷ்ணர்", "நான் இல்லாத, நீ இல்லாத, இந்த அரசர்கள் இல்லாத காலம் ஒருபோதும் இருந்ததில்லை; இனியும் நாம் இல்லாமல் போகும் காலம் ஒருபோதும் வராது.", null], "Gita 2.13": ["கீதை 2.13", "2.13 · ஸ்ரீகிருஷ்ணர்", "இந்த உடலில் ஆத்மா குழந்தைப் பருவம், இளமை, முதுமை வழியாகச் செல்வது போலவே வேறு உடலை அடைகிறது. தீரன் இதனால் மயங்குவதில்லை.", null], "Gita 2.14": ["கீதை 2.14", "2.14 · ஸ்ரீகிருஷ்ணர்", "புலன்களும் பொருள்களும் சேர்வதால் குளிர் வெப்பம், சுக துக்கம் உண்டாகின்றன. இவை வந்து போகின்றன, நிலையானவை அல்ல. பாரதா! இவற்றைப் பொறுத்துக்கொள்ளக் கற்றுக்கொள்.", null], "Gita 2.15": ["கீதை 2.15", "2.15 · ஸ்ரீகிருஷ்ணர்", "இவற்றால் கலங்காமல், சுக துக்கத்தில் சமமாகவும் தீரமாகவும் இருப்பவன் அமிர்தத்துவத்துக்குத் தகுதியானவன்.", null], "Gita 2.16": ["கீதை 2.16", "2.16 · ஸ்ரீகிருஷ்ணர்", "இல்லாததற்கு இருப்பு இல்லை, இருப்பதற்கு ஒருபோதும் இல்லாமை இல்லை. உண்மையைக் கண்டவர்கள் இரண்டின் சாரத்தையும் அறிந்திருக்கிறார்கள்.", null], "Gita 2.17": ["கீதை 2.17", "2.17 · ஸ்ரீகிருஷ்ணர்", "எதனால் இவை அனைத்தும் நிறைந்துள்ளனவோ, அதை அழிவற்றது என்று அறிந்துகொள். அந்த அழிவற்றதை யாராலும் அழிக்க முடியாது.", null], "Gita 2.18": ["கீதை 2.18", "2.18 · ஸ்ரீகிருஷ்ணர்", "இந்த உடல்கள் அழியக்கூடியவை என்று சொல்லப்பட்டுள்ளன, ஆனால் இவற்றில் உறையும் ஆத்மா நிலையானது, அழிவற்றது, அளவிட முடியாதது. ஆகவே பாரதா! போர் புரி.", null], "Gita 2.19": ["கீதை 2.19", "2.19 · ஸ்ரீகிருஷ்ணர்", "ஆத்மாவைக் கொல்பவனாக நினைப்பவனும், கொல்லப்பட்டதாக நினைப்பவனும், இருவரும் அறியாதவர்கள். இது கொல்வதுமில்லை, கொல்லப்படுவதுமில்லை.", null], "Gita 2.21": ["கீதை 2.21", "2.21 · ஸ்ரீகிருஷ்ணர்", "பார்த்தா! ஆத்மாவை அழிவற்றதாக, நிலையானதாக, பிறப்பற்றதாக, மாறாததாக அறிந்தவன் யாரை எப்படிக் கொல்வான், அல்லது கொல்லச் செய்வான்?", null], "Gita 2.23": ["கீதை 2.23", "2.23 · ஸ்ரீகிருஷ்ணர்", "இதை ஆயுதங்கள் வெட்ட முடியாது, நெருப்பு எரிக்க முடியாது, நீர் நனைக்க முடியாது, காற்று உலர்த்த முடியாது.", null], "Gita 2.24": ["கீதை 2.24", "2.24 · ஸ்ரீகிருஷ்ணர்", "இது வெட்டப்படுவதில்லை, எரிவதில்லை, நனைவதில்லை, உலர்வதில்லை. இது நிலையானது, எங்கும் நிறைந்தது, உறுதியானது, அசையாதது, என்றுமுள்ளது.", null], "Gita 2.25": ["கீதை 2.25", "2.25 · ஸ்ரீகிருஷ்ணர்", "இது வெளிப்படாதது, சிந்தனைக்கு எட்டாதது, மாற்றமற்றது என்று சொல்லப்படுகிறது. இதை இவ்வாறு அறிந்து நீ வருந்தக் கூடாது.", null], "Gita 2.26": ["கீதை 2.26", "2.26 · ஸ்ரீகிருஷ்ணர்", "நீ இதை மீண்டும் மீண்டும் பிறந்து இறப்பதாக நினைத்தாலும், நீண்ட கைகளுடையவனே! நீ வருந்தக் கூடாது.", null], "Gita 2.27": ["கீதை 2.27", "2.27 · ஸ்ரீகிருஷ்ணர்", "ஏனெனில் பிறந்தவனுக்கு மரணம் உறுதி, இறந்தவனுக்குப் பிறப்பு உறுதி. ஆகவே தவிர்க்க முடியாததற்காக வருந்தாதே.", null], "Gita 2.28": ["கீதை 2.28", "2.28 · ஸ்ரீகிருஷ்ணர்", "பாரதா! உயிர்கள் பிறப்புக்கு முன் வெளிப்படாதிருந்தன, நடுவில் வெளிப்படுகின்றன, இறப்புக்குப் பின் மீண்டும் வெளிப்படாதவையாகின்றன. இதில் வருந்த என்ன இருக்கிறது?", null], "Gita 2.29": ["கீதை 2.29", "2.29 · ஸ்ரீகிருஷ்ணர்", "ஒருவன் இதை அதிசயமாகப் பார்க்கிறான், ஒருவன் அதிசயமாக விவரிக்கிறான், ஒருவன் அதிசயமாகக் கேட்கிறான்; கேட்ட பிறகும் ஒருவனும் இதைச் சரியாக அறிவதில்லை.", null], "Gita 2.30": ["கீதை 2.30", "2.30 · ஸ்ரீகிருஷ்ணர்", "பாரதா! எல்லோருடைய உடலிலும் உறையும் இந்த ஆத்மா எப்போதும் கொல்லப்பட முடியாதது. ஆகவே நீ எந்த உயிருக்காகவும் வருந்தக் கூடாது.", null], "Gita 2.31": ["கீதை 2.31", "2.31 · ஸ்ரீகிருஷ்ணர்", "உன் தர்மத்தைப் பார்த்தாலும் நீ தடுமாறக் கூடாது; க்ஷத்திரியனுக்குத் தர்மப் போரை விடச் சிறந்தது எதுவும் இல்லை.", null], "Gita 2.32": ["கீதை 2.32", "2.32 · ஸ்ரீகிருஷ்ணர்", "பார்த்தா! தானாகவே வந்த, திறந்த சொர்க்க வாயில் போன்ற இத்தகைய தர்மப் போர் கிடைக்கும் க்ஷத்திரியர்கள் பாக்கியசாலிகள்.", null], "Gita 2.33": ["கீதை 2.33", "2.33 · ஸ்ரீகிருஷ்ணர்", "ஆனால் நீ இந்தத் தர்மப் போரைச் செய்யாவிட்டால், உன் தர்மத்தையும் புகழையும் இழந்து பாவத்துக்கு ஆளாவாய்.", null], "Gita 2.34": ["கீதை 2.34", "2.34 · ஸ்ரீகிருஷ்ணர்", "மக்கள் எப்போதும் உன் அவப்பெயரைப் பற்றிப் பேசுவார்கள்; மதிப்புக்குரியவனுக்கு அவப்பெயர் மரணத்தை விடவும் மோசமானது.", null], "Gita 2.35": ["கீதை 2.35", "2.35 · ஸ்ரீகிருஷ்ணர்", "நீ பயந்து போரிலிருந்து ஓடிவிட்டாய் என்று மகாரதர்கள் நினைப்பார்கள்; உன்னை மிகவும் மதித்தவர்களின் பார்வையில் நீ தாழ்ந்துவிடுவாய்.", null], "Gita 2.36": ["கீதை 2.36", "2.36 · ஸ்ரீகிருஷ்ணர்", "உன் எதிரிகள் உன் வலிமையை இகழ்ந்து சொல்லத் தகாத பல சொற்களைச் சொல்வார்கள். இதை விட வேதனையானது என்ன?", null], "Gita 2.37": ["கீதை 2.37", "2.37 · ஸ்ரீகிருஷ்ணர்", "கொல்லப்பட்டால் சொர்க்கம் அடைவாய்; வென்றால் பூமியின் அரசை அனுபவிப்பாய். ஆகவே கௌந்தேயா! போரிட உறுதிகொண்டு எழுந்திரு.", null], "Gita 2.38": ["கீதை 2.38", "2.38 · ஸ்ரீகிருஷ்ணர்", "சுக துக்கம், லாப நஷ்டம், வெற்றி தோல்வியைச் சமமாகக் கருதிப் போருக்குத் தயாராகு. இவ்வாறு செய்தால் உனக்குப் பாவம் சேராது.", null], "Gita 2.39": ["கீதை 2.39", "2.39 · ஸ்ரீகிருஷ்ணர்", "இந்த ஞானத்தை நான் உனக்குச் சாங்கியக் கோணத்தில் சொன்னேன். இப்போது இதை யோகக் கோணத்தில் கேள்; இந்த அறிவுடன் கூடி நீ கர்ம பந்தத்தை உடைப்பாய்.", null], "Gita 2.40": ["கீதை 2.40", "2.40 · ஸ்ரீகிருஷ்ணர்", "இந்த வழியில் செய்த முயற்சி ஒருபோதும் வீணாவதில்லை, எதிர்விளைவும் இல்லை. இந்தத் தர்மத்தைச் சிறிதளவு கடைப்பிடித்தாலும் பெரும் அச்சத்திலிருந்து காக்கிறது.", null], "Gita 2.41": ["கீதை 2.41", "2.41 · ஸ்ரீகிருஷ்ணர்", "குருநந்தனா! இந்த வழியில் உறுதியான அறிவு ஒன்றே; உறுதியற்றவர்களின் அறிவு பல கிளைகளாகச் சிதறி முடிவற்றதாக இருக்கிறது.", null], "Gita 2.42": ["கீதை 2.42", "2.42 · ஸ்ரீகிருஷ்ணர்", "வேதச் சொற்களிலேயே மகிழ்ந்திருந்து \"இதைத் தவிர வேறொன்றும் இல்லை\" என்று சொல்லும் விவேகமற்றவர்கள்,", null], "Gita 2.43": ["கீதை 2.43", "2.43 · ஸ்ரீகிருஷ்ணர்", "ஆசைகள் நிறைந்து, சொர்க்கத்தையே இலக்காகக் கருதுபவர்கள் இன்பமும் செல்வமும் தரும் சடங்குகளைப் பற்றிக் கவர்ச்சியாகப் பேசுகிறார்கள்; அவற்றின் பலன் மறுபிறவி.", null], "Gita 2.44": ["கீதை 2.44", "2.44 · ஸ்ரீகிருஷ்ணர்", "இன்பத்திலும் செல்வத்திலும் பற்றுடையவர்களும், இத்தகைய பேச்சால் மனம் வழிதவறியவர்களும், அவர்களின் அறிவு தியானத்தில் நிலைப்பதில்லை.", null], "Gita 2.45": ["கீதை 2.45", "2.45 · ஸ்ரீகிருஷ்ணர்", "வேதங்கள் மூன்று குணங்களின் விஷயங்களை விவரிக்கின்றன. அர்ஜுனா! நீ மூன்று குணங்களுக்கும் மேலே உயர்: இருமைகளிலிருந்து விடுபட்டு, எப்போதும் சத்துவத்தில் நிலைத்து, அடைதல் காத்தல் என்ற கவலையின்றி, ஆத்மாவில் நிலைத்திரு.", null], "Gita 2.46": ["கீதை 2.46", "2.46 · ஸ்ரீகிருஷ்ணர்", "சுற்றிலும் நீர் நிறைந்திருக்கும்போது சிறிய கிணற்றுக்கு எவ்வளவு பயன் உள்ளதோ, உண்மையை அறிந்த ஞானிக்கு எல்லா வேதங்களுக்கும் அவ்வளவே பயன்.", null], "Gita 2.49": ["கீதை 2.49", "2.49 · ஸ்ரீகிருஷ்ணர்", "தனஞ்சயா! பலனை விரும்பிச் செய்த செயல் இந்தச் சம அறிவுடன் செய்யும் செயலை விட மிகவும் தாழ்ந்தது. இந்த அறிவைச் சரணடை. பலனுக்காகவே செயல்படுபவர்கள் இரங்கத்தக்கவர்கள்.", null], "Gita 2.50": ["கீதை 2.50", "2.50 · ஸ்ரீகிருஷ்ணர்", "சம அறிவுடையவன் இங்கேயே நல்ல தீய இரு பலன்களிலிருந்தும் விடுபடுகிறான். ஆகவே யோகத்தில் ஈடுபடு: செயலில் திறமையே யோகம்.", null], "Gita 2.51": ["கீதை 2.51", "2.51 · ஸ்ரீகிருஷ்ணர்", "சம அறிவுடைய ஞானிகள் செயலின் பலனைத் துறந்து பிறவிப் பிணைப்பிலிருந்து விடுபடுகிறார்கள், துயரத்துக்கு அப்பாற்பட்ட நிலையை அடைகிறார்கள்.", null], "Gita 2.52": ["கீதை 2.52", "2.52 · ஸ்ரீகிருஷ்ணர்", "உன் அறிவு மயக்கம் என்ற சேற்றைக் கடக்கும்போது, கேட்டவற்றிலும் கேட்கப்போகும் விஷயங்களிலும் நீ பற்றற்றவனாவாய்.", null], "Gita 2.53": ["கீதை 2.53", "2.53 · ஸ்ரீகிருஷ்ணர்", "பல விஷயங்களைக் கேட்டுக் கலங்கிய உன் அறிவு தியானத்தில் அசையாமலும் நிலையாகவும் ஆகும்போது நீ யோகத்தை அடைவாய்.", null], "Gita 2.54": ["கீதை 2.54", "2.54 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: கேசவா! நிலையான அறிவுடைய, சமாதியில் நிலைத்தவனின் அடையாளங்கள் என்ன? அவன் எப்படிப் பேசுகிறான், எப்படி அமர்கிறான், எப்படி நடக்கிறான்?", null], "Gita 2.55": ["கீதை 2.55", "2.55 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீபகவான் சொன்னார்: பார்த்தா! ஒருவன் மனதின் எல்லா ஆசைகளையும் துறந்து, ஆத்மாவால் ஆத்மாவிலேயே திருப்தியுற்றிருக்கும்போது, அவன் ஸ்திதப்ரக்ஞன் எனப்படுகிறான்.", null], "Gita 2.56": ["கீதை 2.56", "2.56 · ஸ்ரீகிருஷ்ணர்", "துயரத்தில் மனம் கலங்காதவன், சுகத்துக்கு ஏங்காதவன், பற்று அச்சம் சினத்திலிருந்து விடுபட்டவன் நிலையான அறிவுடைய முனிவன் எனப்படுகிறான்.", null], "Gita 2.57": ["கீதை 2.57", "2.57 · ஸ்ரீகிருஷ்ணர்", "எதிலும் பற்றில்லாதவன், நல்லது கிடைத்தால் மகிழாதவன், தீயது கிடைத்தால் வெறுக்காதவன், அவன் அறிவு நிலையானது.", null], "Gita 2.58": ["கீதை 2.58", "2.58 · ஸ்ரீகிருஷ்ணர்", "ஆமை தன் உறுப்புகளை உள்ளிழுத்துக்கொள்வது போல, புலன்களைப் பொருள்களிலிருந்து முழுமையாக விலக்கிக்கொள்பவனின் அறிவு நிலையானது.", null], "Gita 2.59": ["கீதை 2.59", "2.59 · ஸ்ரீகிருஷ்ணர்", "பொருள்களை அனுபவிக்காவிட்டால் பொருள்கள் விலகுகின்றன, ஆனால் அவற்றின் சுவை (ஏக்கம்) நீடிக்கிறது. பரமாத்மாவைத் தரிசித்ததும் அந்தச் சுவையும் விலகுகிறது.", null], "Gita 2.60": ["கீதை 2.60", "2.60 · ஸ்ரீகிருஷ்ணர்", "கௌந்தேயா! சஞ்சலமான புலன்கள் முயற்சி செய்யும் அறிவாளியின் மனதையும் வலுக்கட்டாயமாகக் கவர்ந்துவிடுகின்றன.", null], "Gita 2.61": ["கீதை 2.61", "2.61 · ஸ்ரீகிருஷ்ணர்", "எல்லாப் புலன்களையும் அடக்கி, என்னிடம் மனதைச் செலுத்தி யோகத்தில் அமர வேண்டும். யாருடைய புலன்கள் அடங்கியுள்ளனவோ, அவன் அறிவு நிலையானது.", null], "Gita 2.62": ["கீதை 2.62", "2.62 · ஸ்ரீகிருஷ்ணர்", "பொருள்களைப் பற்றி நினைப்பதால் அவற்றில் பற்று உண்டாகிறது; பற்றிலிருந்து ஆசையும், ஆசையிலிருந்து சினமும் எழுகின்றன.", null], "Gita 2.63": ["கீதை 2.63", "2.63 · ஸ்ரீகிருஷ்ணர்", "சினத்திலிருந்து மயக்கம்; மயக்கத்திலிருந்து நினைவுத் தடுமாற்றம்; நினைவுத் தடுமாற்றத்தால் அறிவு அழிவு; அறிவு அழிவால் ஒருவன் வீழ்கிறான்.", null], "Gita 2.64": ["கீதை 2.64", "2.64 · ஸ்ரீகிருஷ்ணர்", "ஆனால் விருப்பு வெறுப்பிலிருந்து விடுபட்டு, கட்டுப்பாட்டில் வைத்த புலன்களுடன் பொருள்களிடையே வாழும் தன்னடக்கமுடையவன் தெளிவை (அமைதியை) அடைகிறான்.", null], "Gita 2.65": ["கீதை 2.65", "2.65 · ஸ்ரீகிருஷ்ணர்", "அந்தத் தெளிவில் எல்லாத் துயரங்களும் நீங்குகின்றன; தெளிந்த மனமுடையவனின் அறிவு விரைவிலேயே நிலைபெறுகிறது.", null], "Gita 2.66": ["கீதை 2.66", "2.66 · ஸ்ரீகிருஷ்ணர்", "அடக்கமற்றவனிடம் விவேகமும் இல்லை, பாவனையும் (தியானமும்) இல்லை. தியானம் இல்லாமல் அமைதி இல்லை, அமைதி இல்லாமல் சுகம் எப்படி?", null], "Gita 2.67": ["கீதை 2.67", "2.67 · ஸ்ரீகிருஷ்ணர்", "மனம் அலையும் புலன்களின் பின்னால் செல்லும்போது, காற்று நீரில் படகை அடித்துச் செல்வது போல அது அறிவைக் கவர்ந்துவிடுகிறது.", null], "Gita 2.68": ["கீதை 2.68", "2.68 · ஸ்ரீகிருஷ்ணர்", "ஆகவே நீண்ட கைகளுடையவனே! யாருடைய புலன்கள் பொருள்களிலிருந்து முழுமையாகத் தடுக்கப்பட்டுள்ளனவோ, அவன் அறிவு நிலையானது.", null], "Gita 2.69": ["கீதை 2.69", "2.69 · ஸ்ரீகிருஷ்ணர்", "எல்லா உயிர்களுக்கும் எது இரவோ அதில் அடக்கமுடையவன் விழித்திருக்கிறான்; எதில் எல்லா உயிர்களும் விழித்திருக்கின்றனவோ அது ஞானியான முனிவருக்கு இரவு.", null], "Gita 2.70": ["கீதை 2.70", "2.70 · ஸ்ரீகிருஷ்ணர்", "நிரம்பிய, அசையாத கடலில் ஆறுகள் புகுந்தாலும் அது கலங்காதது போல, யாரிடம் எல்லா ஆசைகளும் மாற்றமின்றி அடங்குகின்றனவோ, அவன் அமைதியை அடைகிறான்; ஆசைகளின் பின்னால் ஓடுபவன் அல்ல.", null], "Gita 2.71": ["கீதை 2.71", "2.71 · ஸ்ரீகிருஷ்ணர்", "எல்லா ஆசைகளையும் விட்டு, ஏக்கம், 'எனது' என்ற பற்று, அகங்காரம் இன்றி வாழ்பவன் அமைதியை அடைகிறான்.", null], "Gita 2.72": ["கீதை 2.72", "2.72 · ஸ்ரீகிருஷ்ணர்", "பார்த்தா! இது பிராம்மி நிலை. இதை அடைந்தவன் மீண்டும் மயங்குவதில்லை. இறுதிக் காலத்திலும் இதில் நிலைத்து அவன் பிரம்ம நிர்வாணத்தை (பிரம்மத்தின் அமைதியை) அடைகிறான்.", null], "Gita 3.1": ["கீதை 3.1", "3.1 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: ஜனார்த்தனா! நீங்கள் ஞானத்தைச் செயலை விடச் சிறந்ததாகக் கருதினால், கேசவா! என்னை ஏன் இந்தப் பயங்கரச் செயலில் ஈடுபடுத்துகிறீர்கள்?", null], "Gita 3.2": ["கீதை 3.2", "3.2 · அர்ஜுனன்", "உங்கள் கலந்த சொற்களால் என் அறிவு குழம்புகிறது. எனக்கு நன்மை தரும் அந்த ஒரு வழியை உறுதியாகச் சொல்லுங்கள்.", null], "Gita 3.3": ["கீதை 3.3", "3.3 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீபகவான் சொன்னார்: பாவமற்றவனே! நான் முன்பே சொன்னது போல, இந்த உலகில் இரண்டு வழிகள் உள்ளன: சிந்திப்பவர்களுக்கு ஞானயோகம், செயல்படுபவர்களுக்குக் கர்மயோகம்.", null], "Gita 3.4": ["கீதை 3.4", "3.4 · ஸ்ரீகிருஷ்ணர்", "செயல்களைத் தொடங்காமல் இருப்பதால் மட்டும் யாரும் கர்ம பந்தத்திலிருந்து விடுபடுவதில்லை; வெறும் துறவால் சித்தி கிடைப்பதில்லை.", null], "Gita 3.5": ["கீதை 3.5", "3.5 · ஸ்ரீகிருஷ்ணர்", "யாரும் ஒரு கணம் கூடச் செயல் செய்யாமல் இருக்க முடியாது; இயற்கையின் குணங்கள் அனைவரையும் கட்டாயமாகச் செயல்பட வைக்கின்றன.", null], "Gita 3.6": ["கீதை 3.6", "3.6 · ஸ்ரீகிருஷ்ணர்", "செயல் புலன்களை அடக்கி மனதால் பொருள்களைப் பற்றி நினைத்துக்கொண்டிருப்பவன் மூடன், பொய்யொழுக்கமுடையவன் (வேடதாரி) எனப்படுகிறான்.", null], "Gita 3.7": ["கீதை 3.7", "3.7 · ஸ்ரீகிருஷ்ணர்", "ஆனால் அர்ஜுனா! மனதால் புலன்களை அடக்கி, பற்றின்றிச் செயல் புலன்களால் கர்மயோகம் செய்பவன் சிறந்தவன்.", null], "Gita 3.8": ["கீதை 3.8", "3.8 · ஸ்ரீகிருஷ்ணர்", "நீ உன் கடமையைச் செய், ஏனெனில் செயல் செய்யாமல் இருப்பதை விடச் செயல் செய்வது சிறந்தது. செயல் இல்லாமல் உடல் பிழைப்பு கூட நடக்காது.", null], "Gita 3.9": ["கீதை 3.9", "3.9 · ஸ்ரீகிருஷ்ணர்", "யக்ஞத்துக்காக (அர்ப்பணத்துக்காக) செய்யும் செயலைத் தவிர மற்ற செயல்கள் மனிதனைக் கட்டுகின்றன. ஆகவே கௌந்தேயா! பற்றை விட்டு அதே உணர்வுடன் செயல்படு.", null], "Gita 3.10": ["கீதை 3.10", "3.10 · ஸ்ரீகிருஷ்ணர்", "தொடக்கத்தில் பிரஜாபதி யக்ஞத்துடன் மக்களைப் படைத்துச் சொன்னார்: \"இதனால் நீங்கள் செழித்து வளருங்கள்; இது உங்கள் விருப்பங்களை நிறைவேற்றும் காமதேனுவாக இருக்கட்டும்.\"", null], "Gita 3.11": ["கீதை 3.11", "3.11 · ஸ்ரீகிருஷ்ணர்", "இதனால் நீங்கள் தேவர்களை மகிழ்விப்பீர், தேவர்கள் உங்களை மகிழ்விக்கட்டும். ஒருவரையொருவர் பேணி நீங்கள் பரம நன்மையை அடைவீர்கள்.", null], "Gita 3.12": ["கீதை 3.12", "3.12 · ஸ்ரீகிருஷ்ணர்", "யக்ஞத்தால் மகிழ்ந்த தேவர்கள் உங்களுக்கு விரும்பிய இன்பங்களைத் தருவார்கள். அவர்கள் தந்தவற்றை எதையும் திருப்பித் தராமல் அனுபவிப்பவன் திருடனே.", null], "Gita 3.13": ["கீதை 3.13", "3.13 · ஸ்ரீகிருஷ்ணர்", "யக்ஞத்தில் மீந்ததை உண்ணும் நல்லோர் எல்லாப் பாவங்களிலிருந்தும் விடுபடுகிறார்கள்; ஆனால் தங்களுக்காக மட்டுமே சமைப்பவர்கள் பாவத்தையே உண்கிறார்கள்.", null], "Gita 3.14": ["கீதை 3.14", "3.14 · ஸ்ரீகிருஷ்ணர்", "உயிர்கள் உணவிலிருந்தும், உணவு மழையிலிருந்தும், மழை யக்ஞத்திலிருந்தும், யக்ஞம் செயலிலிருந்தும் பிறக்கின்றன.", null], "Gita 3.15": ["கீதை 3.15", "3.15 · ஸ்ரீகிருஷ்ணர்", "செயல் வேதத்திலிருந்தும், வேதம் அழிவற்ற (பரமாத்மா)விலிருந்தும் பிறந்தது என்று அறி. ஆகவே எங்கும் நிறைந்த பிரம்மம் எப்போதும் யக்ஞத்தில் நிலைத்திருக்கிறது.", null], "Gita 3.16": ["கீதை 3.16", "3.16 · ஸ்ரீகிருஷ்ணர்", "பார்த்தா! இவ்வாறு இயக்கப்பட்ட சக்கரத்தைப் பின்பற்றாமல், புலன்களில் மகிழ்ந்து பாவமான வாழ்க்கை வாழ்பவன் வீணாகவே வாழ்கிறான்.", null], "Gita 3.17": ["கீதை 3.17", "3.17 · ஸ்ரீகிருஷ்ணர்", "ஆனால் ஆத்மாவிலேயே மகிழ்ந்து, ஆத்மாவிலேயே நிறைவும் திருப்தியும் உற்றவனுக்குச் செய்ய வேண்டிய கடமை எதுவும் இல்லை.", null], "Gita 3.18": ["கீதை 3.18", "3.18 · ஸ்ரீகிருஷ்ணர்", "அத்தகையவனுக்குச் செயல் செய்வதாலும் பயன் இல்லை, செய்யாமல் இருப்பதாலும் பயன் இல்லை; அவன் எந்த விஷயத்துக்கும் எந்த உயிரையும் சார்ந்திருப்பதில்லை.", null], "Gita 3.19": ["கீதை 3.19", "3.19 · ஸ்ரீகிருஷ்ணர்", "ஆகவே பற்றை விட்டு எப்போதும் செய்ய வேண்டிய செயலைச் செய்துகொண்டிரு. பற்றின்றிச் செயல்படுவதால் மனிதன் பரமாத்மாவை அடைகிறான்.", null], "Gita 3.20": ["கீதை 3.20", "3.20 · ஸ்ரீகிருஷ்ணர்", "ஜனகர் முதலியோர் செயலாலேயே சித்தியை அடைந்தார்கள். உலக நன்மையை (லோகசங்கிரகத்தை) கருதியும் நீ செயல்பட வேண்டும்.", null], "Gita 3.22": ["கீதை 3.22", "3.22 · ஸ்ரீகிருஷ்ணர்", "பார்த்தா! மூன்று உலகங்களிலும் நான் செய்ய வேண்டியது எதுவும் மிஞ்சவில்லை, அடைய வேண்டியதும் இல்லை; இருந்தும் நான் செயலில் ஈடுபட்டிருக்கிறேன்.", null], "Gita 3.23": ["கீதை 3.23", "3.23 · ஸ்ரீகிருஷ்ணர்", "ஏனெனில் நான் கவனமாகச் செயல்படாவிட்டால், மக்கள் எல்லா வகையிலும் என் வழியையே பின்பற்றுவார்கள்.", null], "Gita 3.24": ["கீதை 3.24", "3.24 · ஸ்ரீகிருஷ்ணர்", "நான் செயல்படாவிட்டால் இந்த உலகங்கள் அழிந்துவிடும்; நான் ஒழுங்கின்மைக்குக் காரணமாகி இந்த மக்களை அழிப்பேன்.", null], "Gita 3.25": ["கீதை 3.25", "3.25 · ஸ்ரீகிருஷ்ணர்", "பாரதா! அறிவிலிகள் பற்றுடன் செயல்படுவது போல, ஞானி உலக நன்மை விருப்பத்துடன், பற்றின்றிச் செயல்பட வேண்டும்.", null], "Gita 3.26": ["கீதை 3.26", "3.26 · ஸ்ரீகிருஷ்ணர்", "செயலில் பற்றுடைய அறிவிலிகளின் அறிவில் ஞானி குழப்பம் உண்டாக்கக் கூடாது; தானே யோகத்துடன் செயல்பட்டு அவர்களையும் செயலில் ஈடுபடுத்த வேண்டும்.", null], "Gita 3.27": ["கீதை 3.27", "3.27 · ஸ்ரீகிருஷ்ணர்", "எல்லாச் செயல்களும் இயற்கையின் குணங்களால் நிகழ்கின்றன, ஆனால் அகங்காரத்தால் மயங்கியவன் \"நானே செய்பவன்\" என்று நினைக்கிறான்.", null], "Gita 3.28": ["கீதை 3.28", "3.28 · ஸ்ரீகிருஷ்ணர்", "ஆனால் நீண்ட கைகளுடையவனே! குணங்கள், செயல்களின் பிரிவின் உண்மையை அறிந்தவன் \"குணங்களே குணங்களில் இயங்குகின்றன\" என்று உணர்ந்து பற்றுக்கொள்வதில்லை.", null], "Gita 3.29": ["கீதை 3.29", "3.29 · ஸ்ரீகிருஷ்ணர்", "இயற்கையின் குணங்களால் மயங்கியவர்கள் குணங்களின் செயல்களில் பற்றுடன் இருக்கிறார்கள். முழு ஞானி அரைகுறை புரிதலுடைய மந்த அறிவுடையவர்களைக் கலங்கச் செய்யக் கூடாது.", null], "Gita 3.30": ["கீதை 3.30", "3.30 · ஸ்ரீகிருஷ்ணர்", "எல்லாச் செயல்களையும் எனக்கு அர்ப்பணித்து, மனதை ஆத்மாவில் செலுத்தி, ஆசையும் 'எனது' என்ற பற்றும் இன்றி, துயரம் என்ற காய்ச்சலை விட்டுப் போர் புரி.", null], "Gita 3.31": ["கீதை 3.31", "3.31 · ஸ்ரீகிருஷ்ணர்", "சிரத்தையுடன், குறை காணாமல், எப்போதும் என் இந்தக் கருத்தைப் பின்பற்றுபவர்களும் செயல்களிலிருந்து விடுபடுகிறார்கள்.", null], "Gita 3.32": ["கீதை 3.32", "3.32 · ஸ்ரீகிருஷ்ணர்", "ஆனால் என் இந்தக் கருத்தில் குறை கண்டு இதைப் பின்பற்றாதவர்களை, எல்லா ஞானத்திலும் மயங்கியவர்களாக, விவேகமற்றவர்களாக, அழிந்தவர்களாக அறி.", null], "Gita 3.33": ["கீதை 3.33", "3.33 · ஸ்ரீகிருஷ்ணர்", "ஞானியும் தன் இயல்புக்கேற்பவே நடந்துகொள்கிறான். எல்லா உயிர்களும் தம் இயல்புக்கேற்ப நடக்கின்றன; பிடிவாதமாக அடக்கினால் என்ன ஆகும்?", null], "Gita 3.34": ["கீதை 3.34", "3.34 · ஸ்ரீகிருஷ்ணர்", "புலன்களின் பொருள்களில் விருப்பும் வெறுப்பும் இயல்பாகவே உள்ளன; ஆனால் அவற்றுக்கு அடிமையாகாதே, ஏனெனில் அவை நன்மையின் வழியின் எதிரிகள்.", null], "Gita 3.36": ["கீதை 3.36", "3.36 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: வார்ஷ்ணேயா! பிறகு மனிதன் விரும்பாவிட்டாலும், வலுக்கட்டாயமாகத் தூண்டப்பட்டது போல, ஏன் பாவம் செய்கிறான்?", null], "Gita 3.37": ["கீதை 3.37", "3.37 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீபகவான் சொன்னார்: இது காமம், இதுவே சினம், இது ரஜோ குணத்திலிருந்து பிறக்கிறது. இது ஒருபோதும் திருப்தியடைவதில்லை, பெரும் பாவி. இதையே இங்கே எதிரியாக அறி.", null], "Gita 3.38": ["கீதை 3.38", "3.38 · ஸ்ரீகிருஷ்ணர்", "புகையால் நெருப்பும், தூசியால் கண்ணாடியும், சவ்வால் கருவும் மூடப்பட்டிருப்பது போல, ஆசையால் ஞானம் மூடப்பட்டுள்ளது.", null], "Gita 3.39": ["கீதை 3.39", "3.39 · ஸ்ரீகிருஷ்ணர்", "கௌந்தேயா! ஞானிகளின் இந்த நிரந்தர எதிரியான, ஆசை என்ற ஒருபோதும் திருப்தியடையாத நெருப்பால் ஞானம் மூடப்பட்டுள்ளது.", null], "Gita 3.40": ["கீதை 3.40", "3.40 · ஸ்ரீகிருஷ்ணர்", "புலன்கள், மனம், அறிவு இதன் இருப்பிடங்கள் எனப்படுகின்றன. இவற்றின் மூலம் இது ஞானத்தை மூடி ஜீவாத்மாவை மயக்குகிறது.", null], "Gita 3.41": ["கீதை 3.41", "3.41 · ஸ்ரீகிருஷ்ணர்", "ஆகவே பரதர்களில் சிறந்தவனே! முதலில் புலன்களை அடக்கு, பிறகு ஞானத்தையும் விஞ்ஞானத்தையும் அழிக்கும் இந்தப் பாவியைக் கொன்றுவிடு.", null], "Gita 3.42": ["கீதை 3.42", "3.42 · ஸ்ரீகிருஷ்ணர்", "புலன்கள் (உடலை விட) சிறந்தவை எனப்படுகின்றன; புலன்களை விட மனம் சிறந்தது; மனதை விட அறிவு சிறந்தது; அறிவை விடவும் சிறந்தது அது (ஆத்மா).", null], "Gita 3.43": ["கீதை 3.43", "3.43 · ஸ்ரீகிருஷ்ணர்", "இவ்வாறு ஆத்மாவை அறிவை விடச் சிறந்ததாக அறிந்து, ஆத்மாவால் மனதை நிலைப்படுத்தி, நீண்ட கைகளுடையவனே! வெல்வதற்குக் கடினமான இந்த ஆசை என்ற எதிரியை வெல்.", null], "Gita 4.1": ["கீதை 4.1", "4.1 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீகிருஷ்ணர் சொன்னார்: இந்த அழிவற்ற யோகத்தை நான் சூரிய தேவனான விவஸ்வானுக்குக் கற்பித்தேன். விவஸ்வான் இதை மனுவுக்குச் சொன்னார், மனு இக்ஷ்வாகு மன்னனுக்குச் சொன்னார்.", null], "Gita 4.2": ["கீதை 4.2", "4.2 · ஸ்ரீகிருஷ்ணர்", "இவ்வாறு குரு சீட மரபில் வந்த இந்த யோகத்தை ராஜரிஷிகள் அறிந்தார்கள். ஆனால் அர்ஜுனா, நீண்ட காலம் கழிந்ததும் இந்த யோகம் உலகிலிருந்து மறைந்துவிட்டது.", null], "Gita 4.3": ["கீதை 4.3", "4.3 · ஸ்ரீகிருஷ்ணர்", "இன்று நான் உனக்கு அதே பழைய யோகத்தைச் சொல்லியிருக்கிறேன், ஏனெனில் நீ என் பக்தன், நண்பன். இது மிக உயர்ந்த ரகசியம்.", null], "Gita 4.4": ["கீதை 4.4", "4.4 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: உங்கள் பிறப்பு இப்போதுதான் நிகழ்ந்தது, விவஸ்வானின் பிறப்பு வெகு காலத்துக்கு முன் நிகழ்ந்தது. தொடக்கத்தில் நீங்கள் அவருக்கு இதைக் கற்பித்தீர்கள் என்று நான் எப்படிப் புரிந்துகொள்வது?", null], "Gita 4.5": ["கீதை 4.5", "4.5 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீகிருஷ்ணர் சொன்னார்: அர்ஜுனா, எனக்கும் உனக்கும் பல பிறவிகள் கழிந்துவிட்டன. நான் அவை அனைத்தையும் அறிவேன், நீ அறியமாட்டாய்.", null], "Gita 4.6": ["கீதை 4.6", "4.6 · ஸ்ரீகிருஷ்ணர்", "நான் பிறப்பற்றவன், அழிவற்றவன், எல்லா உயிர்களுக்கும் இறைவன், இருந்தும் என் இயற்கையை என் கட்டுப்பாட்டில் வைத்து என் மாயையால் தோன்றுகிறேன்.", null], "Gita 4.9": ["கீதை 4.9", "4.9 · ஸ்ரீகிருஷ்ணர்", "என் பிறப்பு, செயல்களின் தெய்வீக இயல்பை உண்மையில் அறிந்தவன் உடலை விட்ட பிறகு மீண்டும் பிறப்பதில்லை. அர்ஜுனா, அவன் என்னை அடைகிறான்.", null], "Gita 4.10": ["கீதை 4.10", "4.10 · ஸ்ரீகிருஷ்ணர்", "பற்று, அச்சம், சினத்திலிருந்து விடுபட்டு, என்னிடம் ஒன்றி, என்னைச் சரணடைந்த பலர் ஞானம் என்ற தவத்தால் தூய்மையடைந்து என் நிலையை அடைந்திருக்கிறார்கள்.", null], "Gita 4.11": ["கீதை 4.11", "4.11 · ஸ்ரீகிருஷ்ணர்", "யார் எந்த உணர்வுடன் என்னைச் சரணடைகிறார்களோ, நான் அவர்களை அவ்வாறே ஏற்றுக்கொள்கிறேன். பார்த்தா, மனிதர்கள் அனைவரும் எல்லா வகையிலும் என் வழியிலேயே நடக்கிறார்கள்.", null], "Gita 4.12": ["கீதை 4.12", "4.12 · ஸ்ரீகிருஷ்ணர்", "செயல்களுக்கு விரைவில் பலனை விரும்புபவர்கள் இங்கே தேவர்களை வழிபடுகிறார்கள், ஏனெனில் மனித உலகில் செயலால் வரும் வெற்றி விரைவில் கிடைக்கிறது.", null], "Gita 4.13": ["கீதை 4.13", "4.13 · ஸ்ரீகிருஷ்ணர்", "குணம், செயல்களின் பிரிவுக்கேற்ப நான்கு வர்ணங்களை நான் படைத்தேன். அவற்றைப் படைத்தவனாக இருந்தும் என்னைச் செயலற்றவனாக, அழிவற்றவனாக அறி.", null], "Gita 4.14": ["கீதை 4.14", "4.14 · ஸ்ரீகிருஷ்ணர்", "செயல்கள் என்னைப் பற்றுவதில்லை, எனக்குச் செயலின் பலன் மீது விருப்பம் இல்லை. என்னை இவ்வாறு அறிந்தவனும் செயல்களால் கட்டுப்படுவதில்லை.", null], "Gita 4.15": ["கீதை 4.15", "4.15 · ஸ்ரீகிருஷ்ணர்", "இதை அறிந்து பண்டைய முக்தியை விரும்பியவர்களும் செயல்களைச் செய்தார்கள். ஆகவே முன்னோர்கள் வெகு காலத்துக்கு முன் செய்தது போல நீயும் செயல்படு.", null], "Gita 4.16": ["கீதை 4.16", "4.16 · ஸ்ரீகிருஷ்ணர்", "செயல் என்றால் என்ன, செயலின்மை என்றால் என்ன என்பதில் ஞானிகளும் குழம்புகிறார்கள். நான் உனக்குச் செயலின் ரகசியத்தைச் சொல்வேன், அதை அறிந்து நீ தீமையிலிருந்து விடுபடுவாய்.", null], "Gita 4.17": ["கீதை 4.17", "4.17 · ஸ்ரீகிருஷ்ணர்", "செயலைப் புரிந்துகொள்ள வேண்டும், விகர்மத்தையும் (தவறான செயலையும்) புரிந்துகொள்ள வேண்டும், செயலின்மையையும். செயலின் போக்கு மிகவும் ஆழமானது.", null], "Gita 4.18": ["கீதை 4.18", "4.18 · ஸ்ரீகிருஷ்ணர்", "செயலில் செயலின்மையையும், செயலின்மையில் செயலையும் காண்பவனே மனிதர்களில் அறிவாளி. அவன் எல்லாச் செயல்களையும் செய்தாலும் யோகத்தில் நிலைத்திருக்கிறான்.", null], "Gita 4.19": ["கீதை 4.19", "4.19 · ஸ்ரீகிருஷ்ணர்", "யாருடைய எல்லாச் செயல்களும் ஆசையும் சுயநல எண்ணமும் இன்றி இருக்கின்றனவோ, யாருடைய செயல்கள் ஞான நெருப்பில் எரிந்துவிட்டனவோ, அவனை ஞானிகள் பண்டிதன் என்கிறார்கள்.", null], "Gita 4.20": ["கீதை 4.20", "4.20 · ஸ்ரீகிருஷ்ணர்", "செயலின் பலன் மீதான பற்றை விட்டு, எப்போதும் நிறைவுடன், யாரையும் சாராமல் இருப்பவன், செயலில் முழுமையாக ஈடுபட்டிருந்தாலும் எதையும் செய்வதில்லை.", null], "Gita 4.21": ["கீதை 4.21", "4.21 · ஸ்ரீகிருஷ்ணர்", "ஆசையற்றவன், மனதையும் புலன்களையும் அடக்கியவன், எல்லாச் சேமிப்பையும் துறந்தவன், உடலுக்காக மட்டும் செயல்படும்போது எந்தப் பாவத்தையும் அடைவதில்லை.", null], "Gita 4.22": ["கீதை 4.22", "4.22 · ஸ்ரீகிருஷ்ணர்", "தானாகக் கிடைப்பதில் திருப்தியுற்று, சுக துக்கம் போன்ற இருமைகளுக்கு அப்பாற்பட்டு, பொறாமையின்றி, வெற்றி தோல்வியில் சமமாக இருப்பவன் செயல்பட்டாலும் கட்டுப்படுவதில்லை.", null], "Gita 4.23": ["கீதை 4.23", "4.23 · ஸ்ரீகிருஷ்ணர்", "பற்றற்றவனும் விடுபட்டவனும், மனம் ஞானத்தில் நிலைத்தவனும், யக்ஞ உணர்வுடன் செயல்படுபவனுமானவனின் எல்லாச் செயல்களும் முழுமையாகக் கரைந்துவிடுகின்றன.", null], "Gita 4.24": ["கீதை 4.24", "4.24 · ஸ்ரீகிருஷ்ணர்", "அர்ப்பணம் பிரம்மம், அவிசு பிரம்மம், பிரம்மம் என்ற நெருப்பில் பிரம்மத்தால் ஆகுதி அளிக்கப்படுகிறது. ஒவ்வொரு செயலிலும் பிரம்மத்தைக் காண்பவன் பிரம்மத்தையே அடைகிறான்.", null], "Gita 4.25": ["கீதை 4.25", "4.25 · ஸ்ரீகிருஷ்ணர்", "சில யோகிகள் தேவர்களுக்காக யக்ஞம் செய்கிறார்கள். மற்றவர்கள் பிரம்மம் என்ற நெருப்பில் யக்ஞத்தாலேயே யக்ஞத்தை ஆகுதியாக்குகிறார்கள்.", null], "Gita 4.26": ["கீதை 4.26", "4.26 · ஸ்ரீகிருஷ்ணர்", "சிலர் கேட்டல் முதலிய புலன்களை அடக்கம் என்ற நெருப்பில் அர்ப்பணிக்கிறார்கள். மற்றவர்கள் ஒலி முதலிய பொருள்களைப் புலன்கள் என்ற நெருப்பில் அர்ப்பணிக்கிறார்கள்.", null], "Gita 4.27": ["கீதை 4.27", "4.27 · ஸ்ரீகிருஷ்ணர்", "மற்றவர்கள் புலன்கள், பிராணன்களின் எல்லாச் செயல்களையும் ஞானத்தால் ஏற்றப்பட்ட தன்னடக்கம் என்ற யோக நெருப்பில் அர்ப்பணிக்கிறார்கள்.", null], "Gita 4.28": ["கீதை 4.28", "4.28 · ஸ்ரீகிருஷ்ணர்", "சிலர் செல்வத்தை யக்ஞமாக்குகிறார்கள், சிலர் தவத்தை, சிலர் யோகத்தை; உறுதியான விரதமுடைய சில சாதகர்கள் சுவாத்தியாயத்தையும் ஞானத்தையும் யக்ஞமாக்குகிறார்கள்.", null], "Gita 4.29": ["கீதை 4.29", "4.29 · ஸ்ரீகிருஷ்ணர்", "மற்றவர்கள், பிராணாயாமத்தில் ஈடுபட்ட சாதகர்கள், பிராணனை அபானனிலும் அபானனைப் பிராணனிலும் அர்ப்பணிக்கிறார்கள், இரண்டின் இயக்கத்தையும் தடுத்து.", null], "Gita 4.30": ["கீதை 4.30", "4.30 · ஸ்ரீகிருஷ்ணர்", "மற்றவர்கள் அளவான உணவு உண்டு பிராணன்களைப் பிராணன்களில் அர்ப்பணிக்கிறார்கள். இவர்கள் அனைவரும் யக்ஞத்தை அறிந்தவர்கள், யக்ஞத்தால் அவர்களின் குறைகள் நீங்குகின்றன.", null], "Gita 4.31": ["கீதை 4.31", "4.31 · ஸ்ரீகிருஷ்ணர்", "யக்ஞத்தில் மீந்த அமிர்தம் போன்ற உணவை உண்பவர்கள் சனாதன பிரம்மத்தை அடைகிறார்கள். யக்ஞம் செய்யாதவனுக்கு இந்த உலகமே இல்லை, பிறகு மறு உலகம் எப்படி?", null], "Gita 4.32": ["கீதை 4.32", "4.32 · ஸ்ரீகிருஷ்ணர்", "வேதங்களில் இவ்வாறு பல வகை யக்ஞங்கள் சொல்லப்பட்டுள்ளன. அவை அனைத்தும் செயலிலிருந்து பிறக்கின்றன என்று அறி. இதை அறிந்து நீ விடுபடுவாய்.", null], "Gita 4.33": ["கீதை 4.33", "4.33 · ஸ்ரீகிருஷ்ணர்", "பரந்தபா, பொருளால் செய்யும் யக்ஞத்தை விட ஞான யக்ஞம் சிறந்தது. பார்த்தா, எல்லாச் செயல்களும் முழுமையாக ஞானத்திலேயே முடிகின்றன.", null], "Gita 4.34": ["கீதை 4.34", "4.34 · ஸ்ரீகிருஷ்ணர்", "அந்த ஞானத்தைப் பணிவான வணக்கத்தாலும், உண்மையான கேள்விகளாலும், சேவையாலும் அறிந்துகொள். உண்மையைக் கண்ட ஞானிகள் உனக்கு அந்த ஞானத்தைக் கற்பிப்பார்கள்.", null], "Gita 4.35": ["கீதை 4.35", "4.35 · ஸ்ரீகிருஷ்ணர்", "பாண்டவா, அதை அறிந்த பிறகு நீ மீண்டும் ஒருபோதும் இத்தகைய மயக்கத்தில் விழமாட்டாய். அதனால் நீ எல்லா உயிர்களையும் உன்னிலும் பிறகு என்னிலும் காண்பாய்.", null], "Gita 4.36": ["கீதை 4.36", "4.36 · ஸ்ரீகிருஷ்ணர்", "நீ பாவிகள் அனைவரிலும் பெரும் பாவியாக இருந்தாலும், ஞானம் என்ற படகால் எல்லாப் பாவங்களையும் கடப்பாய்.", null], "Gita 4.37": ["கீதை 4.37", "4.37 · ஸ்ரீகிருஷ்ணர்", "அர்ஜுனா, எரியும் நெருப்பு விறகுகளைச் சாம்பலாக்குவது போல, ஞான நெருப்பு எல்லாச் செயல்களையும் சாம்பலாக்குகிறது.", null], "Gita 4.39": ["கீதை 4.39", "4.39 · ஸ்ரீகிருஷ்ணர்", "சிரத்தையுடையவன், அதில் ஈடுபட்டவன், புலன்களை அடக்கியவன் ஞானத்தை அடைகிறான். ஞானத்தை அடைந்து அவன் விரைவிலேயே பரம அமைதியை அடைகிறான்.", null], "Gita 4.40": ["கீதை 4.40", "4.40 · ஸ்ரீகிருஷ்ணர்", "அறிவிலியும், சிரத்தையற்றவனும், ஐயம் நிறைந்தவனும் அழிகிறான். ஐயம் கொள்பவனுக்கு இந்த உலகமும் இல்லை, மறு உலகமும் இல்லை, சுகமும் இல்லை.", null], "Gita 4.41": ["கீதை 4.41", "4.41 · ஸ்ரீகிருஷ்ணர்", "தனஞ்சயா, யோகத்தால் செயல்களைத் துறந்தவன், ஞானத்தால் ஐயங்கள் வெட்டப்பட்டவன், ஆத்மாவில் நிலைத்தவன், அவனைச் செயல்கள் கட்டுவதில்லை.", null], "Gita 4.42": ["கீதை 4.42", "4.42 · ஸ்ரீகிருஷ்ணர்", "ஆகவே அறியாமையில் பிறந்து இதயத்தில் அமர்ந்திருக்கும் இந்த ஐயத்தை ஞானம் என்ற வாளால் வெட்டிவிடு. யோகத்தைச் சரணடை. பாரதா, எழுந்திரு!", null], "Gita 5.1": ["கீதை 5.1", "5.1 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: கிருஷ்ணா, நீங்கள் செயல்களைத் துறப்பதைப் புகழ்கிறீர்கள், பிறகு கர்மயோகத்தையும். இவ்விரண்டில் உறுதியாக எது சிறந்ததோ அதை எனக்குச் சொல்லுங்கள்.", null], "Gita 5.2": ["கீதை 5.2", "5.2 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீகிருஷ்ணர் சொன்னார்: கர்ம சன்னியாசமும் கர்மயோகமும் இரண்டுமே பரம நன்மைக்கு வழிநடத்துகின்றன. ஆனால் அவ்விரண்டில் கர்ம சன்னியாசத்தை விடக் கர்மயோகம் சிறந்தது.", null], "Gita 5.3": ["கீதை 5.3", "5.3 · ஸ்ரீகிருஷ்ணர்", "வெறுக்காதவனும், விரும்பாதவனுமானவனை நிரந்தரச் சன்னியாசி என்று அறி. நீண்ட கைகளுடையவனே, இருமைகளிலிருந்து விடுபட்ட அவன் எளிதில் பந்தத்திலிருந்து விடுபடுகிறான்.", null], "Gita 5.4": ["கீதை 5.4", "5.4 · ஸ்ரீகிருஷ்ணர்", "ஞான வழியும் (சாங்கியம்) கர்ம வழியும் (யோகம்) வேறுவேறு என்று அறிவிலிகள் சொல்கிறார்கள், ஞானிகள் அல்ல. இவற்றில் எதாவது ஒன்றில் சரியாக நடப்பவன் இரண்டின் பலனையும் அடைகிறான்.", null], "Gita 5.5": ["கீதை 5.5", "5.5 · ஸ்ரீகிருஷ்ணர்", "ஞான வழியால் எந்த இடம் கிடைக்கிறதோ, அதுவே கர்ம வழியாலும் கிடைக்கிறது. சாங்கியத்தையும் யோகத்தையும் ஒன்றாகக் காண்பவனே உண்மையில் காண்கிறான்.", null], "Gita 5.6": ["கீதை 5.6", "5.6 · ஸ்ரீகிருஷ்ணர்", "ஆனால் நீண்ட கைகளுடையவனே, கர்மயோகம் இல்லாமல் சன்னியாசத்தை அடைவது கடினம். யோகத்தில் ஈடுபட்ட முனிவர் விரைவிலேயே பிரம்மத்தை அடைகிறார்.", null], "Gita 5.7": ["கீதை 5.7", "5.7 · ஸ்ரீகிருஷ்ணர்", "யோகத்தில் நிலைத்தவன், தூய இதயமுடையவன், மனதையும் புலன்களையும் வென்றவன், எல்லா உயிர்களிலும் தன் ஆத்மாவையே காண்பவன், செயல்பட்டாலும் ஒட்டுவதில்லை.", null], "Gita 5.8": ["கீதை 5.8", "5.8 · ஸ்ரீகிருஷ்ணர்", "உண்மையை அறிந்த யோகி பார்க்கும்போதும், கேட்கும்போதும், தொடும்போதும், முகரும்போதும், உண்ணும்போதும், நடக்கும்போதும், உறங்கும்போதும், சுவாசிக்கும்போதும் \"நான் எதையும் செய்யவில்லை\" என்றே கருதுகிறான்,", null], "Gita 5.9": ["கீதை 5.9", "5.9 · ஸ்ரீகிருஷ்ணர்", "பேசும்போதும், விடும்போதும், பற்றும்போதும், கண்களைத் திறந்து மூடும்போதும், புலன்கள் மட்டுமே தம் பொருள்களில் இயங்குகின்றன என்று உணர்ந்து.", null], "Gita 5.11": ["கீதை 5.11", "5.11 · ஸ்ரீகிருஷ்ணர்", "யோகிகள் பற்றை விட்டு, தங்கள் தூய்மைக்காக, உடல், மனம், அறிவு, வெறும் புலன்களால் செயல்படுகிறார்கள்.", null], "Gita 5.12": ["கீதை 5.12", "5.12 · ஸ்ரீகிருஷ்ணர்", "யோகத்தில் நிலைத்தவன் செயலின் பலனை விட்டு நிலையான அமைதியை அடைகிறான். நிலையற்றவன் ஆசையால் தூண்டப்பட்டு, பலனில் பற்றுக்கொண்டு கட்டுப்படுகிறான்.", null], "Gita 5.13": ["கீதை 5.13", "5.13 · ஸ்ரீகிருஷ்ணர்", "மனதால் எல்லாச் செயல்களையும் துறந்து, அடக்கமுடைய ஆத்மா ஒன்பது வாயில்களுடைய நகரத்தில், அதாவது உடலில், சுகமாக வாழ்கிறது, செயல்படுவதுமில்லை, செயல்பட வைப்பதுமில்லை.", null], "Gita 5.14": ["கீதை 5.14", "5.14 · ஸ்ரீகிருஷ்ணர்", "இறைவன் மக்களின் செய்பவன் என்ற நிலையையோ, செயலையோ, செயல் பலன் தொடர்பையோ படைப்பதில்லை. இவை அனைத்தையும் இயல்பே (இயற்கையே) செய்கிறது.", null], "Gita 5.15": ["கீதை 5.15", "5.15 · ஸ்ரீகிருஷ்ணர்", "எங்கும் நிறைந்த இறைவன் யாருடைய பாவத்தையும் புண்ணியத்தையும் ஏற்பதில்லை. ஞானம் அறியாமையால் மூடப்பட்டுள்ளது, அதனாலேயே உயிர்கள் மயங்குகின்றன.", null], "Gita 5.16": ["கீதை 5.16", "5.16 · ஸ்ரீகிருஷ்ணர்", "ஆனால் யாருடைய அறியாமை ஆத்மஞானத்தால் அழிந்ததோ, அவர்களின் ஞானம் சூரியனைப் போல ஒளிர்ந்து பரம தத்துவத்தை வெளிப்படுத்துகிறது.", null], "Gita 5.17": ["கீதை 5.17", "5.17 · ஸ்ரீகிருஷ்ணர்", "யாருடைய அறிவு அதில், ஆத்மா அதில், நிஷ்டை அதில், இலக்கு அதுவே, ஞானத்தால் யாருடைய குறைகள் கழுவப்பட்டனவோ, அவர்கள் திரும்பி வராத நிலையை அடைகிறார்கள்.", null], "Gita 5.19": ["கீதை 5.19", "5.19 · ஸ்ரீகிருஷ்ணர்", "யாருடைய மனம் சமநிலையில் நிலைத்ததோ, அவர்கள் இங்கேயே உலகை வென்றுவிட்டார்கள். பிரம்மம் குறையற்றது, எல்லோரிலும் சமமானது, ஆகவே அவர்கள் பிரம்மத்தில் நிலைத்திருக்கிறார்கள்.", null], "Gita 5.20": ["கீதை 5.20", "5.20 · ஸ்ரீகிருஷ்ணர்", "பிடித்தது கிடைத்தால் மிகவும் மகிழக் கூடாது, பிடிக்காதது கிடைத்தால் கலங்கக் கூடாது. நிலையான அறிவுடைய, மயக்கமற்ற பிரம்மஞானி பிரம்மத்தில் நிலைத்திருக்கிறான்.", null], "Gita 5.21": ["கீதை 5.21", "5.21 · ஸ்ரீகிருஷ்ணர்", "வெளி இன்பங்களில் பற்றுக்கொள்ளாமல் ஒருவன் உள்ளே சுகத்தைக் காண்கிறான். யோகத்தால் பிரம்மத்துடன் இணைந்த அவன் ஒருபோதும் குறையாத சுகத்தை அனுபவிக்கிறான்.", null], "Gita 5.22": ["கீதை 5.22", "5.22 · ஸ்ரீகிருஷ்ணர்", "புலன்களின் தொடர்பால் பிறக்கும் இன்பங்கள் துயரத்துக்கே காரணங்கள். கௌந்தேயா, அவற்றுக்குத் தொடக்கமும் முடிவும் உண்டு; அறிவாளி அவற்றில் மகிழ்வதில்லை.", null], "Gita 5.23": ["கீதை 5.23", "5.23 · ஸ்ரீகிருஷ்ணர்", "உடலை விடுவதற்கு முன் இங்கேயே காமம், சினத்தின் வேகத்தைத் தாங்கக்கூடியவனே யோகி, அவனே சுகமான மனிதன்.", null], "Gita 5.24": ["கீதை 5.24", "5.24 · ஸ்ரீகிருஷ்ணர்", "யாருடைய சுகம் உள்ளே இருக்கிறதோ, யாருடைய ஆனந்தம் உள்ளே இருக்கிறதோ, யாருடைய ஒளி உள்ளே இருக்கிறதோ, அந்த யோகி பிரம்ம வடிவாகி பிரம்ம நிர்வாணத்தை (பரம அமைதியை) அடைகிறான்.", null], "Gita 5.25": ["கீதை 5.25", "5.25 · ஸ்ரீகிருஷ்ணர்", "யாருடைய குறைகள் நீங்கினவோ, ஐயங்கள் வெட்டப்பட்டனவோ, யார் அடக்கமுடையவர்களோ, எல்லா உயிர்களின் நலனில் ஈடுபட்டிருக்கிறார்களோ, அந்த ரிஷிகள் பிரம்ம நிர்வாணத்தை அடைகிறார்கள்.", null], "Gita 5.26": ["கீதை 5.26", "5.26 · ஸ்ரீகிருஷ்ணர்", "காமம், சினத்திலிருந்து விடுபட்டவர்கள், மனதை அடக்கியவர்கள், ஆத்மாவை அறிந்தவர்கள், அவர்களுக்குப் பிரம்ம நிர்வாணம் எல்லாப் பக்கமும் அருகிலேயே உள்ளது.", null], "Gita 5.27": ["கீதை 5.27", "5.27 · ஸ்ரீகிருஷ்ணர்", "வெளிப் பொருள்களை வெளியிலேயே விட்டு, பார்வையைப் புருவங்களின் நடுவில் நிறுத்தி, மூக்கில் இயங்கும் பிராணனையும் அபானனையும் சமமாக்கி,", null], "Gita 5.28": ["கீதை 5.28", "5.28 · ஸ்ரீகிருஷ்ணர்", "புலன்கள், மனம், அறிவை அடக்கி, முக்தியை இலக்காகக் கொண்ட, விருப்பம், அச்சம், சினம் இல்லாத முனிவர் எப்போதும் விடுபட்டவரே.", null], "Gita 5.29": ["கீதை 5.29", "5.29 · ஸ்ரீகிருஷ்ணர்", "என்னை எல்லா யக்ஞங்களுக்கும் தவங்களுக்கும் அனுபவிப்பவனாக, எல்லா உலகங்களின் மகேசுவரனாக, எல்லா உயிர்களின் நண்பனாக அறிந்து ஒருவன் அமைதியை அடைகிறான்.", null], "Gita 6.1": ["கீதை 6.1", "6.1 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீகிருஷ்ணர் சொன்னார்: செயலின் பலனைச் சாராமல் செய்ய வேண்டிய செயலைச் செய்பவனே சன்னியாசியும் யோகியும்; வெறுமனே நெருப்பையோ செயலையோ விட்டவன் அல்ல.", null], "Gita 6.2": ["கீதை 6.2", "6.2 · ஸ்ரீகிருஷ்ணர்", "பாண்டவா, எதைச் சன்னியாசம் என்கிறார்களோ, அதையே யோகம் என்று அறி. சுயநல எண்ணங்களை விடாமல் யாரும் யோகியாவதில்லை.", null], "Gita 6.3": ["கீதை 6.3", "6.3 · ஸ்ரீகிருஷ்ணர்", "யோகத்தில் ஏற விரும்பும் முனிவருக்குச் செயலே சாதனம் என்று சொல்லப்பட்டது. யோகத்தில் ஏறிய பிறகு அவருக்கே அமைதி (சமம்) சாதனம் என்று சொல்லப்பட்டது.", null], "Gita 6.4": ["கீதை 6.4", "6.4 · ஸ்ரீகிருஷ்ணர்", "ஒருவன் புலன்களின் பொருள்களிலோ செயல்களிலோ பற்றுக்கொள்ளாமல், எல்லா எண்ணங்களையும் விடும்போது, அவனை யோகாரூடன் என்கிறார்கள்.", null], "Gita 6.6": ["கீதை 6.6", "6.6 · ஸ்ரீகிருஷ்ணர்", "தன்னை வென்றவனுக்கு அவன் மனம் நண்பன். வெல்லாதவனுக்கு அதே மனம் எதிரியைப் போல நடந்துகொள்கிறது.", null], "Gita 6.7": ["கீதை 6.7", "6.7 · ஸ்ரீகிருஷ்ணர்", "தன்னை வென்று அமைதியாக இருப்பவனின் மனம் குளிர் வெப்பம், சுக துக்கம், மானம் அவமானத்திலும் பரமாத்மாவில் நிலைத்திருக்கிறது.", null], "Gita 6.8": ["கீதை 6.8", "6.8 · ஸ்ரீகிருஷ்ணர்", "ஞானத்தாலும் அனுபவத்தாலும் நிறைவுற்றவன், அசையாதவன், புலன்களை வென்றவன், மண்கட்டியையும் கல்லையும் பொன்னையும் சமமாகக் காண்பவன், அந்த யோகி யுக்தன் எனப்படுகிறான்.", null], "Gita 6.9": ["கீதை 6.9", "6.9 · ஸ்ரீகிருஷ்ணர்", "நலம் விரும்பி, நண்பன், எதிரி, நடுநிலையாளன், மத்தியஸ்தன், வெறுப்பவன், உறவினன், நல்லவன், பாவி அனைவரிடமும் சம அறிவு கொண்டவன் அவனை விடவும் சிறந்தவன்.", null], "Gita 6.10": ["கீதை 6.10", "6.10 · ஸ்ரீகிருஷ்ணர்", "யோகி தனிமையான இடத்தில் தனியாக இருந்து, மனதையும் உடலையும் அடக்கி, ஆசையும் சேமிப்பும் இன்றி, இடைவிடாமல் மனதை ஆத்மாவில் செலுத்த வேண்டும்.", null], "Gita 6.11": ["கீதை 6.11", "6.11 · ஸ்ரீகிருஷ்ணர்", "தூய்மையான இடத்தில் தன் உறுதியான ஆசனத்தை அமைக்க வேண்டும், மிக உயரமும் இல்லை மிகத் தாழ்வும் இல்லை, அதன் மேல் வரிசையாகத் தர்ப்பைப் புல், மான் தோல், துணி விரிக்கப்பட்டிருக்க வேண்டும்.", null], "Gita 6.12": ["கீதை 6.12", "6.12 · ஸ்ரீகிருஷ்ணர்", "அதில் அமர்ந்து, மனதை ஒருமுகப்படுத்தி, எண்ணங்களையும் புலன்களின் செயல்களையும் அடக்கி, தன்னைத் தூய்மைப்படுத்திக்கொள்ள யோகத்தைப் பயில வேண்டும்.", null], "Gita 6.13": ["கீதை 6.13", "6.13 · ஸ்ரீகிருஷ்ணர்", "உடல், தலை, கழுத்தை நேராகவும் அசையாமலும் வைத்து, நிலையாக, அங்குமிங்கும் பார்க்காமல் தன் மூக்கு நுனியில் பார்வையை நிறுத்த வேண்டும்.", null], "Gita 6.14": ["கீதை 6.14", "6.14 · ஸ்ரீகிருஷ்ணர்", "அமைதியாகவும் அச்சமின்றியும், பிரம்மச்சரிய விரதத்தில் உறுதியாக இருந்து, மனதை அடக்கி, என்னிடம் சித்தத்தைச் செலுத்தி, என்னையே இலக்காகக் கொண்டு அமர வேண்டும்.", null], "Gita 6.15": ["கீதை 6.15", "6.15 · ஸ்ரீகிருஷ்ணர்", "இவ்வாறு எப்போதும் பயிற்சி செய்து, மனதை அடக்கிய யோகி என்னில் நிலைத்த பரம நிர்வாணம் என்ற அமைதியை அடைகிறான்.", null], "Gita 6.16": ["கீதை 6.16", "6.16 · ஸ்ரீகிருஷ்ணர்", "அர்ஜுனா, யோகம் அதிகமாக உண்பவனுக்குக் கைகூடுவதில்லை, அறவே உண்ணாதவனுக்கும் இல்லை, அதிகமாக உறங்குபவனுக்கும் இல்லை, அதிகமாக விழித்திருப்பவனுக்கும் இல்லை.", null], "Gita 6.18": ["கீதை 6.18", "6.18 · ஸ்ரீகிருஷ்ணர்", "அடக்கப்பட்ட சித்தம் ஆத்மாவில் மட்டும் நிலைத்து, எல்லா ஆசைகளிலிருந்தும் விருப்பமற்றதாகும்போது, அவனை யோகயுக்தன் என்கிறார்கள்.", null], "Gita 6.19": ["கீதை 6.19", "6.19 · ஸ்ரீகிருஷ்ணர்", "\"காற்றில்லாத இடத்தில் வைத்த விளக்கு அசையாதது போல\": சித்தம் அடங்கி தியானத்தில் ஒன்றிய யோகிக்கு இதுவே உவமையாகச் சொல்லப்பட்டது.", null], "Gita 6.20": ["கீதை 6.20", "6.20 · ஸ்ரீகிருஷ்ணர்", "யோகப் பயிற்சியால் கட்டுப்படுத்தப்பட்ட சித்தம் அமைதியடையும்போது, ஒருவன் தன்னால் ஆத்மாவைக் கண்டு ஆத்மாவிலேயே திருப்தியுற்றிருக்கும்போது,", null], "Gita 6.21": ["கீதை 6.21", "6.21 · ஸ்ரீகிருஷ்ணர்", "அறிவால் உணரப்படும், புலன்களுக்கு அப்பாற்பட்ட அந்த முடிவற்ற ஆனந்தத்தை அவன் அறியும்போது, அதில் நிலைத்து மீண்டும் ஒருபோதும் உண்மையிலிருந்து விலகாதபோது,", null], "Gita 6.22": ["கீதை 6.22", "6.22 · ஸ்ரீகிருஷ்ணர்", "எதை அடைந்து அவன் வேறு எந்த லாபத்தையும் அதை விடப் பெரியதாகக் கருதுவதில்லையோ, எதில் நிலைத்து மிகப் பெரிய துயரத்தாலும் கலங்குவதில்லையோ,", null], "Gita 6.23": ["கீதை 6.23", "6.23 · ஸ்ரீகிருஷ்ணர்", "அதையே யோகம் என்று அறி: துயரத்தின் தொடர்பிலிருந்து விடுதலை. இந்த யோகத்தை உறுதியான தீர்மானத்துடனும் சோர்வின்றியும் பயில வேண்டும்.", null], "Gita 6.24": ["கீதை 6.24", "6.24 · ஸ்ரீகிருஷ்ணர்", "சுயநல எண்ணங்களிலிருந்து எழும் எல்லா ஆசைகளையும் முழுமையாக விட்டு, மனதாலேயே புலன்களின் கூட்டத்தை எல்லாப் பக்கங்களிலிருந்தும் தடுத்து,", null], "Gita 6.25": ["கீதை 6.25", "6.25 · ஸ்ரீகிருஷ்ணர்", "மெல்ல மெல்ல, பொறுமையுடன் பற்றிய அறிவுடன் அமைதியடைய வேண்டும். மனதை ஆத்மாவில் நிலைநிறுத்தி வேறு எதையும் நினைக்கக் கூடாது.", null], "Gita 6.26": ["கீதை 6.26", "6.26 · ஸ்ரீகிருஷ்ணர்", "அலையும், நிலையற்ற மனம் எங்கெங்கு அலைகிறதோ, அங்கங்கிருந்து அதைத் திரும்பக் கொண்டுவந்து ஆத்மாவின் கட்டுப்பாட்டுக்குள்ளேயே கொண்டுவர வேண்டும்.", null], "Gita 6.27": ["கீதை 6.27", "6.27 · ஸ்ரீகிருஷ்ணர்", "யாருடைய மனம் அமைதியாக இருக்கிறதோ, யாருடைய சஞ்சலம் (ரஜோ குணம்) அடங்கியதோ, குறையற்றவனாகப் பிரம்ம வடிவானவனோ, அந்த யோகிக்கு உயர்ந்த ஆனந்தம் கிடைக்கிறது.", null], "Gita 6.28": ["கீதை 6.28", "6.28 · ஸ்ரீகிருஷ்ணர்", "இவ்வாறு எப்போதும் பயிற்சி செய்து, குறையற்ற யோகி எளிதாகவே பிரம்மத்தின் தொடுகை என்ற முடிவற்ற ஆனந்தத்தை அனுபவிக்கிறான்.", null], "Gita 6.29": ["கீதை 6.29", "6.29 · ஸ்ரீகிருஷ்ணர்", "யோகத்தில் நிலைத்தவன் ஆத்மாவை எல்லா உயிர்களிலும், எல்லா உயிர்களையும் ஆத்மாவிலும் காண்கிறான், எங்கும் சமமாகக் காண்கிறான்.", null], "Gita 6.30": ["கீதை 6.30", "6.30 · ஸ்ரீகிருஷ்ணர்", "என்னை எங்கும் காண்பவனுக்கும், அனைத்தையும் என்னில் காண்பவனுக்கும் நான் ஒருபோதும் மறைவதில்லை, அவனும் எனக்கு ஒருபோதும் மறைவதில்லை.", null], "Gita 6.31": ["கீதை 6.31", "6.31 · ஸ்ரீகிருஷ்ணர்", "ஒருமையில் நிலைத்து என்னை எல்லா உயிர்களிலும் உள்ளவனாகக் கருதி வழிபடும் யோகி, அவன் எப்படி வாழ்ந்தாலும் என்னிலேயே வாழ்கிறான்.", null], "Gita 6.32": ["கீதை 6.32", "6.32 · ஸ்ரீகிருஷ்ணர்", "அர்ஜுனா, தன்னோடு ஒப்பிட்டு அனைவரின் சுக துக்கத்தையும் சமமாகக் காண்பவன் பரம யோகியாகக் கருதப்படுகிறான்.", null], "Gita 6.33": ["கீதை 6.33", "6.33 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: மதுசூதனா, நீங்கள் சொன்ன சமநிலை யோகம், மனதின் சஞ்சலத்தால் அதன் நிலையான நிலையை என்னால் காண முடியவில்லை.", null], "Gita 6.34": ["கீதை 6.34", "6.34 · அர்ஜுனன்", "கிருஷ்ணா, மனம் சஞ்சலமானது: கலக்குவது, வலிமையானது, பிடிவாதமானது. அதை அடக்குவது காற்றைத் தடுப்பது போலக் கடினமாக எனக்குத் தோன்றுகிறது.", null], "Gita 6.36": ["கீதை 6.36", "6.36 · ஸ்ரீகிருஷ்ணர்", "மனம் அடங்காதவனுக்கு யோகத்தை அடைவது கடினம் என்பது என் கருத்து. ஆனால் அடக்கமுடையவனாக முயன்றுகொண்டிருப்பவன் சரியான வழியால் அதை அடைய முடியும்.", null], "Gita 6.37": ["கீதை 6.37", "6.37 · அர்ஜுனன்", "அர்ஜுனன் சொன்னான்: கிருஷ்ணா, சிரத்தை இருந்தும் முழு முயற்சி செய்யாதவன், மனம் யோகத்திலிருந்து விலகியவன், யோகத்தின் சித்தியை அடையாதவன், அவன் கதி என்ன?", null], "Gita 6.38": ["கீதை 6.38", "6.38 · அர்ஜுனன்", "நீண்ட கைகளுடையவனே, அவன் இரு பக்கமும் வழிதவறி, ஆதாரமின்றி, பிரம்மத்தின் வழியில் மயங்கி, சிதறிய மேகம் போல அழிந்துவிடமாட்டானா?", null], "Gita 6.39": ["கீதை 6.39", "6.39 · அர்ஜுனன்", "கிருஷ்ணா, என் இந்த ஐயத்தை முழுமையாக நீக்குங்கள். உங்களைத் தவிர இந்த ஐயத்தை நீக்கக்கூடியவர் யாரும் இல்லை.", null], "Gita 6.40": ["கீதை 6.40", "6.40 · ஸ்ரீகிருஷ்ணர்", "ஸ்ரீகிருஷ்ணர் சொன்னார்: பார்த்தா, அத்தகையவனுக்கு இந்த உலகிலும் அழிவில்லை, மறு உலகிலும் அழிவில்லை. அன்பனே, நன்மை செய்பவன் யாரும் தீய கதியை அடைவதில்லை.", null], "Gita 6.41": ["கீதை 6.41", "6.41 · ஸ்ரீகிருஷ்ணர்", "புண்ணியம் செய்தவர்களின் உலகங்களை அடைந்து, அங்கே பல ஆண்டுகள் வாழ்ந்து, யோகத்திலிருந்து விலகியவன் தூய்மையான, செல்வச் செழிப்புடையவர்களின் வீட்டில் பிறக்கிறான்.", null], "Gita 6.42": ["கீதை 6.42", "6.42 · ஸ்ரீகிருஷ்ணர்", "அல்லது அவன் அறிவாளிகளான யோகிகளின் குலத்திலேயே பிறக்கிறான். அத்தகைய பிறப்பு இந்த உலகில் மிகவும் அரிது.", null], "Gita 6.43": ["கீதை 6.43", "6.43 · ஸ்ரீகிருஷ்ணர்", "அங்கே அவனுக்கு முற்பிறவியின் அறிவு மீண்டும் கிடைக்கிறது, குருநந்தனா, அங்கிருந்து அவன் சித்திக்காக இன்னும் அதிகமாக முயல்கிறான்.", null], "Gita 6.44": ["கீதை 6.44", "6.44 · ஸ்ரீகிருஷ்ணர்", "அதே பழைய பயிற்சியால் அவன் விரும்பாவிட்டாலும் முன்னோக்கி இழுக்கப்படுகிறான். யோகத்தை அறிய மட்டுமே விரும்புபவனும் வேதச் சடங்குகளைக் கடந்து செல்கிறான்.", null], "Gita 6.45": ["கீதை 6.45", "6.45 · ஸ்ரீகிருஷ்ணர்", "ஆனால் முயற்சியுடன் சாதனை செய்யும் யோகி, குறைகளிலிருந்து தூய்மையடைந்து, பல பிறவிகளில் சித்தியடைந்து, பரம கதியை அடைகிறான்.", null], "Gita 6.46": ["கீதை 6.46", "6.46 · ஸ்ரீகிருஷ்ணர்", "யோகி தவசிகளை விடச் சிறந்தவன், ஞானிகளை விடவும் சிறந்தவனாகக் கருதப்படுகிறான், சடங்குகள் செய்பவர்களை விடவும் சிறந்தவன். ஆகவே அர்ஜுனா, யோகியாகு.", null], "Gita 6.47": ["கீதை 6.47", "6.47 · ஸ்ரீகிருஷ்ணர்", "எல்லா யோகிகளிலும், சிரத்தையுடன், தன் உள்மனதை என்னிடம் செலுத்தி என்னை வழிபடுபவனை நான் மிகச் சிறந்த யோகியாகக் கருதுகிறேன்.", null], "Katha Upanishad 2.3.11": ["கட உபநிடதம் 2.3.11", "புலன்களை நிலைப்படுத்துவதே யோகம்", "புலன்களை இவ்வாறு உறுதியாகக் கட்டுப்படுத்துவதே யோகம் என்று கருதப்படுகிறது. அப்போது மனிதன் விழிப்புடன் இருக்கிறான், ஏனெனில் யோகம் வருவதும் உண்டு, போவதும் உண்டு.", "உபநிடதங்களில் யோகம் என்ற சொல்லின் மிகப் பழமையான பயன்பாடுகளில் இதுவும் ஒன்று: இதன் தொடர்பு புலன்களின் மீதான கட்டுப்பாட்டுடன், உடலின் நெகிழ்வுத்தன்மையுடன் அல்ல."], "Yoga Sutra 1.2": ["யோக சூத்திரம் 1.2", "மனதின் அலைகளை அமைதிப்படுத்துவதே யோகம்", "சித்தத்தின் விருத்திகளை அடக்குவதே யோகம்.", "ஒரு ஏரியை நினைத்துப் பாருங்கள். காற்று நின்றதும் நீர் அமைதியாகி அடிப்பகுதி தெளிவாகத் தெரிகிறது. மனதைப் பற்றிப் பதஞ்சலி சொல்வது இதுவே."], "Yoga Sutra 2.29": ["யோக சூத்திரம் 2.29", "யோகத்தின் எட்டு அங்கங்கள்", "இயமம், நியமம், ஆசனம், பிராணாயாமம், பிரத்தியாகாரம், தாரணை, தியானம், சமாதி: இவை எட்டு அங்கங்கள்.", null], "Yoga Sutra 1.12": ["யோக சூத்திரம் 1.12", "பயிற்சியும் வைராக்கியமும்", "பயிற்சியாலும் வைராக்கியத்தாலும் சித்த விருத்திகள் அடங்குகின்றன.", "கீதை 6.35-இல் கிருஷ்ணரும் இதையே சொல்கிறார்: மனம் சஞ்சலமானது, ஆனால் பயிற்சியாலும் வைராக்கியத்தாலும் கட்டுப்படுகிறது."], "Yoga Sutra 1.14": ["யோக சூத்திரம் 1.14", "பயிற்சி எப்படி உறுதியாகிறது", "நீண்ட காலம், இடைவிடாமல், சிரத்தையுடன் செய்யப்படும்போது பயிற்சி உறுதியாகிறது.", "தினமும் பத்து நிமிடங்கள், மாதம் ஒருமுறை இரண்டு மணி நேரத்தை விட மிக அதிகம் பயன் தருகின்றன."], "Yoga Sutra 1.33": ["யோக சூத்திரம் 1.33", "தூய மனதிற்கு நான்கு உணர்வுகள்", "மகிழ்ச்சியானவரிடம் நட்பு, துன்பப்படுபவரிடம் கருணை, நல்லோரிடம் மகிழ்வு, தீயோரிடம் பொருட்படுத்தாமை என்ற உணர்வுகளால் சித்தம் தூய்மையாகிறது.", "நண்பனுக்குப் பரிசு கிடைத்தது: பொறாமை அல்ல, மகிழ்ச்சி. யாரோ துன்பத்தில்: உதவி. யாரோ நல்லது செய்தார்: பாராட்டு. யாரோ கடுமையாக நடந்தார்: அவரை மனதில் குடியேற விடாதீர்கள்."], "Yoga Sutra 2.46": ["யோக சூத்திரம் 2.46", "உறுதியானதும் இனிமையானதும்", "ஆசனம் உறுதியாகவும் இனிமையாகவும் இருக்கட்டும்.", "ஏதேனும் ஆசனம் வலி தந்தாலோ வலுக்கட்டாயம் செய்ய வைத்தாலோ, அது இன்னும் உங்கள் ஆசனம் அல்ல. தளர்த்துங்கள்."], "Charaka Samhita, Sutrasthana 30.26": ["சரக சம்ஹிதை, சூத்திரஸ்தானம் 30.26", "ஆயுர்வேதத்தின் இரண்டு நோக்கங்கள்", "இதன் நோக்கம் ஆரோக்கியமானவரின் ஆரோக்கியத்தைக் காப்பதும், நோயாளியின் நோயைத் தணிப்பதும்.", "ஆரோக்கியமாக இருப்பது முதலில் வருவதைக் கவனியுங்கள். ஆயுர்வேதத்தின் பெரும்பகுதி தினசரி ஒழுங்கு, உணவு, பருவங்கள் பற்றியது, மருந்துகள் பற்றியது அல்ல."], "Sushruta Samhita, Sutrasthana 15": ["சுஸ்ருத சம்ஹிதை, சூத்திரஸ்தானம் 15", "உண்மையில் ஆரோக்கியமானவர் யார்?", "யாருடைய தோஷங்கள் சமநிலையில் உள்ளனவோ, அக்னி சமமாக உள்ளதோ, தாதுக்களும் மலங்களும் சரியாகச் செயல்படுகின்றனவோ, யாருடைய ஆத்மாவும் புலன்களும் மனமும் மகிழ்ச்சியாக உள்ளனவோ, அவரே ஆரோக்கியமானவர் எனப்படுகிறார்.", "இரண்டாயிரம் ஆண்டுகளுக்கு முன்பும் ஆரோக்கியம் என்றால் சரியாக இயங்கும் உடல் மட்டுமல்ல, மகிழ்ச்சியான மனமும் தான்."]};